// Global error handler to catch unexpected errors (e.g., from browser extensions)
window.addEventListener('error', function(e) {
    // Ignore errors from browser extensions or third-party scripts
    if (e.filename && (e.filename.includes('spoofer') || e.filename.includes('contentScript') || e.filename.includes('extension') || e.filename.includes('chrome-extension'))) {
        e.preventDefault();
        e.stopPropagation();
        return false;
    }
    // Only log errors that are not from extensions
    if (!e.message || (!e.message.includes('spoofer') && !e.message.includes('extension'))) {
        console.warn('[GuardLink Mobile] JavaScript error caught (non-blocking):', e.message, e.filename, e.lineno);
    }
}, true);

// Handle unhandled promise rejections
window.addEventListener('unhandledrejection', function(e) {
    // Ignore errors from browser extensions
    if (e.reason && (typeof e.reason === 'string' && (e.reason.includes('spoofer') || e.reason.includes('extension')))) {
        e.preventDefault();
        e.stopPropagation();
        return false;
    }
    // Only log rejections that are not from extensions
    if (!e.reason || (typeof e.reason === 'string' && !e.reason.includes('spoofer') && !e.reason.includes('extension'))) {
        console.warn('[GuardLink Mobile] Unhandled promise rejection (non-blocking):', e.reason);
    }
});

// CRITICAL FIX: Ensure buttons and forms work even if JavaScript has errors
// Add a fallback that ensures all interactive elements are clickable
document.addEventListener('DOMContentLoaded', function() {
    // Clear safe-area vars to avoid layout shifts in the Android app.
    (function resetNavSafeArea() {
        var root = document.documentElement;
        root.style.setProperty('--gp-safe-top', '0px');
        root.style.setProperty('--gp-safe-bottom', '0px');
    })();
    // Ensure all interactive elements have proper pointer events
    setTimeout(function() {
        const allInteractive = document.querySelectorAll('.guardpro-mobile button, .guardpro-mobile .btn, .guardpro-mobile form, .guardpro-mobile a, .guardpro-mobile input[type="submit"]');
        allInteractive.forEach(function(el) {
            try {
                // Force enable pointer events
                if (el.style) {
                    el.style.pointerEvents = 'auto';
                }
                // Ensure element is not disabled (unless it should be)
                if (el.disabled && el.type !== 'submit' && !el.hasAttribute('data-disabled')) {
                    // Don't enable disabled elements, but log for debugging
                    console.log('[GuardLink Mobile] Element is disabled:', el);
                }
            } catch (e) {
                // Ignore errors when setting styles
            }
        });
        console.log('[GuardLink Mobile] Interactive elements checked and enabled');
    }, 100);
});

// Minimal PWA registration
if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/guardpro/mobile/sw.js')
        .then(reg => console.log('SW registered:', reg))
        .catch(err => console.log('SW registration failed:', err));
}

// ── Offline / Online status banner ────────────────────────
(function () {
    const offBanner  = document.getElementById('gp-offline-banner');
    const syncBanner = document.getElementById('gp-sync-banner');
    let queuedCount = 0;

    function updateBanners() {
        if (!navigator.onLine) {
            if (offBanner)  offBanner.style.display  = '';
            if (syncBanner) syncBanner.style.display = 'none';
        } else {
            if (offBanner) offBanner.style.display = 'none';
            const q = parseInt(localStorage.getItem('gp_offline_queue_count') || '0', 10);
            if (q > 0) {
                if (syncBanner) {
                    syncBanner.innerHTML = '<i class="fa fa-refresh fa-spin me-1"></i>Syncing ' + q + ' queued item' + (q > 1 ? 's' : '') + '…';
                    syncBanner.style.display = '';
                }
                setTimeout(function () {
                    localStorage.removeItem('gp_offline_queue_count');
                    if (syncBanner) syncBanner.style.display = 'none';
                }, 4000);
            } else {
                if (syncBanner) syncBanner.style.display = 'none';
            }
        }
    }

    // Queue POST when offline (checkpoints + simple forms)
    const _origFetch = window.fetch;
    window.fetch = async function (input, init) {
        if (!navigator.onLine && init && (init.method || '').toUpperCase() === 'POST') {
            try {
                const url = typeof input === 'string' ? input : input.url;
                const body = init.body || '';
                const queued = JSON.parse(localStorage.getItem('gp_offline_queue') || '[]');
                queued.push({ url, body: typeof body === 'string' ? body : '', ts: Date.now() });
                localStorage.setItem('gp_offline_queue', JSON.stringify(queued));
                localStorage.setItem('gp_offline_queue_count', queued.length);
                console.log('[GuardLink] Queued offline request:', url);
            } catch (e) { /* storage full — ignore */ }
            return new Response(JSON.stringify({result:{success:false,offline:true}}),
                { status: 202, headers: {'Content-Type':'application/json'} });
        }
        return _origFetch.apply(this, arguments);
    };

    // Flush queue when back online
    window.addEventListener('online', async function () {
        updateBanners();
        const queued = JSON.parse(localStorage.getItem('gp_offline_queue') || '[]');
        if (!queued.length) return;
        for (const item of queued) {
            try {
                await _origFetch(item.url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: item.body,
                });
            } catch (e) {
                console.warn('[GuardLink] Failed to replay queued request:', e);
            }
        }
        localStorage.removeItem('gp_offline_queue');
        localStorage.removeItem('gp_offline_queue_count');
        if (syncBanner) setTimeout(function () { syncBanner.style.display = 'none'; }, 4000);
    });

    window.addEventListener('offline', updateBanners);
    updateBanners();
}());

// Install prompt
let deferredPrompt;
window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    // Show install button if needed
});

// Ensure navigation links work properly on mobile
document.addEventListener('DOMContentLoaded', function() {
    try {
        // Fix navigation links - ensure they're clickable
        const navLinks = document.querySelectorAll('.guardpro-mobile-nav .nav-link');
        navLinks.forEach(function(link) {
            try {
                // Ensure link is properly styled for touch
                link.style.touchAction = 'manipulation';
                link.style.webkitTapHighlightColor = 'rgba(26, 35, 126, 0.2)';
                link.style.cursor = 'pointer';
                link.style.pointerEvents = 'auto';

                // CRITICAL FIX: Don't add event listeners that might interfere
                // Links should work normally without JavaScript interference
                // Only ensure CSS is set for proper touch handling
            } catch (err) {
                console.warn('[GuardLink Mobile] Error setting up nav link:', err);
            }
        });

        // Ensure all buttons work properly - FIXED: Don't interfere with form submissions
        const buttons = document.querySelectorAll('.guardpro-mobile .btn, .guardpro-mobile button');
        buttons.forEach(function(btn) {
            try {
                // Skip if it's a modal toggle button (handled by Bootstrap)
                if (btn.hasAttribute('data-bs-toggle') && btn.getAttribute('data-bs-toggle') === 'modal') {
                    return;
                }

                // Ensure button is touchable - only set CSS, don't interfere with events
                btn.style.touchAction = 'manipulation';
                btn.style.webkitTapHighlightColor = 'rgba(0, 0, 0, 0.1)';
                btn.style.cursor = 'pointer';
                btn.style.pointerEvents = 'auto';

                // CRITICAL FIX: Don't add event listeners that might interfere
                // Form submit buttons and links should work normally
                // Only add visual feedback, not event handlers that could block default behavior

            } catch (err) {
                console.warn('[GuardLink Mobile] Error setting up button:', err);
            }
        });

        // Ensure all forms can submit properly
        const forms = document.querySelectorAll('.guardpro-mobile form');
        forms.forEach(function(form) {
            try {
                form.style.pointerEvents = 'auto';
                // Don't interfere with form submission - let onsubmit handlers work
            } catch (err) {
                console.warn('[GuardLink Mobile] Error setting up form:', err);
            }
        });

        // Ensure all links work properly
        const links = document.querySelectorAll('.guardpro-mobile a');
        links.forEach(function(link) {
            try {
                link.style.pointerEvents = 'auto';
                link.style.touchAction = 'manipulation';
                // Don't interfere with link navigation
            } catch (err) {
                console.warn('[GuardLink Mobile] Error setting up link:', err);
            }
        });

        console.log('[GuardLink Mobile] Navigation and buttons initialized');
    } catch (err) {
        console.error('[GuardLink Mobile] Error initializing navigation:', err);
    }
});

document.addEventListener('click', function (e) {
    var btn = e.target && e.target.closest && e.target.closest('[data-bs-dismiss="alert"]');
    if (!btn) return;
    var alert = btn.closest('.alert');
    if (alert) alert.remove();
});

if (typeof window.getLocationAndSubmit === 'undefined') {
function getLocationAndSubmit(form, event) {
    try {
        console.log('[GuardLink Mobile] getLocationAndSubmit called');
        console.log('[GuardLink Mobile] Form:', form);
        console.log('[GuardLink Mobile] Event:', event);

        // Safety check: if form or event is missing, allow normal submission
        if (!form || !event) {
            console.warn('[GuardLink Mobile] Form or event missing, allowing normal submission');
            return true;
        }

        if (navigator.geolocation) {
            console.log('[GuardLink Mobile] Geolocation available, preventing default');
            event.preventDefault();
            event.stopPropagation();

            const latField = form.querySelector('[name="latitude"]');
            const lngField = form.querySelector('[name="longitude"]');

            console.log('[GuardLink Mobile] Latitude field:', latField);
            console.log('[GuardLink Mobile] Longitude field:', lngField);

            // Show loading state
            const submitBtn = form.querySelector('button[type="submit"]');
            const originalText = submitBtn ? submitBtn.innerHTML : '';
            const originalDisabled = submitBtn ? submitBtn.disabled : false;

            if (submitBtn) {
                submitBtn.disabled = true;
                submitBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Getting location...';
            }

            // Set a timeout to ensure form submits even if geolocation hangs
            const submitTimeout = setTimeout(function() {
                console.warn('[GuardLink Mobile] Location timeout, submitting form without location');
                if (submitBtn) {
                    submitBtn.disabled = originalDisabled;
                    submitBtn.innerHTML = originalText;
                }
                try {
                    form.submit();
                } catch (e) {
                    console.error('[GuardLink Mobile] Error submitting form:', e);
                    // Last resort: trigger click on submit button
                    if (submitBtn) {
                        submitBtn.disabled = false;
                        submitBtn.click();
                    }
                }
            }, 6000); // 6 second timeout

            navigator.geolocation.getCurrentPosition(
                function(position) {
                    clearTimeout(submitTimeout);
                    console.log('[GuardLink Mobile] Location captured:', position.coords.latitude, position.coords.longitude);
                    if (latField) latField.value = position.coords.latitude;
                    if (lngField) lngField.value = position.coords.longitude;

                    if (submitBtn) {
                        submitBtn.disabled = originalDisabled;
                        submitBtn.innerHTML = originalText;
                    }

                    try {
                        form.submit();
                    } catch (e) {
                        console.error('[GuardLink Mobile] Error submitting form after location:', e);
                        // Last resort: trigger click on submit button
                        if (submitBtn) {
                            submitBtn.disabled = false;
                            submitBtn.click();
                        }
                    }
                },
                function(error) {
                    clearTimeout(submitTimeout);
                    // Submit without location on error
                    console.warn('[GuardLink Mobile] Location error:', error);
                    if (submitBtn) {
                        submitBtn.disabled = originalDisabled;
                        submitBtn.innerHTML = originalText;
                    }

                    // Submit form anyway
                    try {
                        form.submit();
                    } catch (e) {
                        console.error('[GuardLink Mobile] Error submitting form after location error:', e);
                        // Last resort: trigger click on submit button
                        if (submitBtn) {
                            submitBtn.disabled = false;
                            submitBtn.click();
                        }
                    }
                },
                { timeout: 5000, enableHighAccuracy: true, maximumAge: 30000 }
            );
            return false;
        } else {
            console.log('[GuardLink Mobile] Geolocation not available, submitting form directly');
            return true; // Allow normal form submission
        }
    } catch (error) {
        console.error('[GuardLink Mobile] Error in getLocationAndSubmit:', error);
        // On any error, allow normal form submission
        return true;
    }
}

// Ensure function is available globally
window.getLocationAndSubmit = getLocationAndSubmit;
console.log('[GuardLink Mobile] getLocationAndSubmit function defined and available globally');
}

// Check if GPS tracker is available
if (typeof window.gpsTracker !== 'undefined') {
    console.log('[GuardLink Mobile] GPS tracker available');

    // Function to request location permission (must be called from user interaction)
    window.requestLocationPermission = function() {
        if (!navigator.geolocation) {
            alert('Geolocation is not supported by your browser');
            return;
        }

        console.log('[GuardLink Mobile] Requesting location permission (user clicked button)...');

        // Request permission - this MUST be triggered by user interaction
        navigator.geolocation.getCurrentPosition(
            function(position) {
                console.log('[GuardLink Mobile] ✓ Location permission GRANTED');
                console.log('[GuardLink Mobile] Current location:', position.coords.latitude, position.coords.longitude);

                // Hide permission banner
                const banner = document.getElementById('location-permission-banner');
                if (banner) banner.style.display = 'none';

                // Start GPS tracking now that we have permission
                console.log('[GuardLink Mobile] Starting GPS tracker...');
                window.gpsTracker.startTracking();

                // Show success message
                const successAlert = document.createElement('div');
                successAlert.className = 'alert alert-success alert-dismissible fade show mb-3';
                successAlert.innerHTML = '<i class="fa fa-check-circle me-2"></i><strong>Location tracking enabled!</strong> Your location will be updated automatically every 5 minutes. <button type="button" class="btn-close" data-bs-dismiss="alert"></button>';
                const container = document.querySelector('.container-fluid.p-3');
                if (container) {
                    container.insertBefore(successAlert, container.firstChild);
                    setTimeout(function() { 
                        if (successAlert.parentNode) successAlert.remove(); 
                    }, 8000);
                }

                // Store permission status
                localStorage.setItem('gps_permission_granted', 'true');
            },
            function(error) {
                console.error('[GuardLink Mobile] ✗ Location permission DENIED:', error);
                let errorMsg = '⚠️ Location Access Denied\n\n';
                if (error.code === 1) {
                    errorMsg += 'You blocked location access. To enable:\n\n';
                    errorMsg += '1. Click the lock icon in your browser address bar\n';
                    errorMsg += '2. Allow location access\n';
                    errorMsg += '3. Refresh this page';
                } else if (error.code === 2) {
                    errorMsg += 'Location information is unavailable. Please check your device settings.';
                } else if (error.code === 3) {
                    errorMsg += 'Location request timed out. Please try again.';
                }
                alert(errorMsg);
            },
            { 
                enableHighAccuracy: true, 
                timeout: 10000, 
                maximumAge: 0 
            }
        );
    };

    // Check permission status using Permissions API (if supported)
    async function checkLocationPermission() {
        console.log('[GuardLink Mobile] Checking location permission status...');

        // Check localStorage first
        if (localStorage.getItem('gps_permission_granted') === 'true') {
            console.log('[GuardLink Mobile] Permission previously granted, attempting to start tracking...');
            try {
                window.gpsTracker.startTracking();
                return true;
            } catch (e) {
                console.warn('[GuardLink Mobile] Could not start tracking:', e);
            }
        }

        // Try Permissions API if available
        if (navigator.permissions && navigator.permissions.query) {
            try {
                const result = await navigator.permissions.query({ name: 'geolocation' });
                console.log('[GuardLink Mobile] Permission state:', result.state);

                if (result.state === 'granted') {
                    console.log('[GuardLink Mobile] Permission granted, starting tracker...');
                    window.gpsTracker.startTracking();
                    return true;
                } else if (result.state === 'prompt' || result.state === 'denied') {
                    console.log('[GuardLink Mobile] Permission not granted, showing banner...');
                    const banner = document.getElementById('location-permission-banner');
                    if (banner) banner.style.display = 'block';
                    return false;
                }
            } catch (e) {
                console.warn('[GuardLink Mobile] Permissions API not fully supported:', e);
            }
        }

        // Fallback: just show the banner
        console.log('[GuardLink Mobile] Cannot determine permission status, showing banner...');
        const banner = document.getElementById('location-permission-banner');
        if (banner) banner.style.display = 'block';
        return false;
    }

    // Check permission on page load
    checkLocationPermission();

} else {
    console.warn('[GuardLink Mobile] GPS tracker not available - gps_tracker.js may not be loaded');
}

// Panic Button Hold-to-Activate
let panicHoldTimer = null;
let panicHoldStartTime = null;
let panicAnimationFrame = null;

window.startPanicHold = function(event) {
    event.preventDefault();

    const button = document.getElementById('panicButton');
    const progress = document.getElementById('panicProgress');
    const text = document.getElementById('panicButtonText');
    const form = document.getElementById('panicForm');

    // Vibrate on touch start (if supported)
    if ('vibrate' in navigator) {
        navigator.vibrate(50);
    }

    panicHoldStartTime = Date.now();
    const holdDuration = 3000; // 3 seconds

    // Update progress bar animation
    function updateProgress() {
        const elapsed = Date.now() - panicHoldStartTime;
        const percentage = Math.min((elapsed / holdDuration) * 100, 100);

        if (progress) {
            progress.style.height = percentage + '%';
        }

        if (text) {
            const remaining = Math.ceil((holdDuration - elapsed) / 1000);
            if (remaining > 0) {
                text.textContent = 'Hold ' + remaining + 's';
            } else {
                text.textContent = 'Sending...';
            }
        }

        if (elapsed < holdDuration) {
            panicAnimationFrame = requestAnimationFrame(updateProgress);
        }
    }

    updateProgress();

    // Set timer for full hold
    panicHoldTimer = setTimeout(function() {
        console.log('[GuardLink] Panic button held for 3 seconds - triggering alert');

        // Strong vibration pattern for confirmation
        if ('vibrate' in navigator) {
            navigator.vibrate([200, 100, 200, 100, 200]);
        }

        // Visual confirmation
        if (button) {
            button.classList.add('animate__animated', 'animate__pulse');
        }
        if (text) {
            text.textContent = 'SENDING!';
        }

        // Get location and submit
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                function(position) {
                    document.getElementById('panic-lat').value = position.coords.latitude;
                    document.getElementById('panic-lng').value = position.coords.longitude;
                    form.submit();
                },
                function(error) {
                    console.warn('Could not get location for panic:', error);
                    form.submit();
                },
                { timeout: 3000, enableHighAccuracy: true }
            );
        } else {
            form.submit();
        }
    }, holdDuration);
};

window.cancelPanicHold = function() {
    if (panicHoldTimer) {
        clearTimeout(panicHoldTimer);
        panicHoldTimer = null;
    }

    if (panicAnimationFrame) {
        cancelAnimationFrame(panicAnimationFrame);
        panicAnimationFrame = null;
    }

    const progress = document.getElementById('panicProgress');
    const text = document.getElementById('panicButtonText');

    if (progress) {
        progress.style.transition = 'height 0.2s ease-out';
        progress.style.height = '0%';
        setTimeout(function() {
            progress.style.transition = 'none';
        }, 200);
    }

    if (text) {
        text.textContent = 'Hold for 3s';
    }

    panicHoldStartTime = null;
};

// Global scanner instance
let tourScanner = null;
let currentCheckpointId = null;
let scanSubmitInProgress = false;
let currentTourLogId = null;
let currentScanType = 'qr';
let pendingCheckpointScanId = null;
let passiveTourNfcActive = false;
let passiveTourScanLookup = {};
let passiveTourLastScanKey = '';
let passiveTourLastScanAt = 0;
const PASSIVE_SCAN_DEBOUNCE_MS = 3500;

function showPassiveToast(message, type) {
    var toast = document.getElementById('passiveNfcToast');
    if (!toast) return;
    toast.className = 'guardpro-passive-toast alert py-2 mb-0 alert-' + (type || 'info');
    toast.textContent = message;
    toast.style.display = 'block';
    clearTimeout(showPassiveToast._hideTimer);
    showPassiveToast._hideTimer = setTimeout(function() {
        toast.style.display = 'none';
    }, type === 'danger' ? 5000 : 3500);
}

function buildPassiveTourScanLookup(config) {
    var lookup = {};
    if (!config || !config.checkpoints) return lookup;
    config.checkpoints.forEach(function(cp) {
        if (cp.qr_code) {
            lookup[String(cp.qr_code).trim()] = cp.id;
        }
        if (cp.nfc_tag_id) {
            lookup[String(cp.nfc_tag_id).trim().toLowerCase()] = cp.id;
        }
        if (cp.nfc_tag_normalized) {
            lookup[String(cp.nfc_tag_normalized).trim().toLowerCase()] = cp.id;
        }
    });
    return lookup;
}

function lookupPassiveCheckpointId(scanData) {
    if (!scanData) return null;
    var key = String(scanData).trim().toLowerCase();
    if (passiveTourScanLookup[key]) {
        return passiveTourScanLookup[key];
    }
    if (typeof guardproFormatNfcUid === 'function') {
        var colon = guardproFormatNfcUid(scanData);
        if (colon && passiveTourScanLookup[colon.toLowerCase()]) {
            return passiveTourScanLookup[colon.toLowerCase()];
        }
    }
    return null;
}

function updatePassiveNfcBannerState(listening) {
    var banner = document.getElementById('passiveNfcBanner');
    var enableBtn = document.getElementById('passiveNfcEnableBtn');
    var title = document.getElementById('passiveNfcBannerTitle');
    var text = document.getElementById('passiveNfcBannerText');
    if (!banner) return;
    banner.style.display = 'block';
    if (listening) {
        banner.classList.add('listening');
        if (title) title.textContent = 'NFC scan active';
        if (text) text.textContent = ' — tap any tag';
        if (enableBtn) enableBtn.style.display = 'none';
    } else {
        banner.classList.remove('listening');
        if (title) title.textContent = 'NFC tap-to-scan';
        if (text) text.textContent = ' — enable to scan without a button';
        if (enableBtn) enableBtn.style.display = 'inline-block';
    }
}

async function startPassiveTourNfc() {
    if (passiveTourNfcActive || !window.GUARDPRO_ACTIVE_TOUR) return;
    var isNative = window.isNativeApp || (typeof AndroidBridge !== 'undefined');
    if (!isNative && !('NDEFReader' in window)) {
        showPassiveToast('NFC is not available in this browser. Use the Guard Pro app or Chrome on Android.', 'warning');
        return;
    }
    if (!isNative) {
        try {
            var probe = new NDEFReader();
            await probe.scan();
            probe.onreading = function() {};
        } catch (e) {
            console.warn('[Passive NFC] Permission probe failed:', e);
        }
    }
    passiveTourNfcActive = true;
    updatePassiveNfcBannerState(true);
    if (isNative) {
        tourScanner = { type: 'nfc', native: true, passive: true };
        console.log('[Passive NFC] Native foreground dispatch active');
        return;
    }
    try {
        var nfcReader = new NDEFReader();
        await nfcReader.scan();
        nfcReader.onreading = function(ev) {
            var ndefText = typeof guardproExtractNdefText === 'function'
                ? guardproExtractNdefText(ev.message) : '';
            var payload = typeof guardproResolveNfcScanPayload === 'function'
                ? guardproResolveNfcScanPayload(ndefText, ev.serialNumber)
                : (ev.serialNumber || ndefText);
            handlePassiveTourNfcScan(payload);
        };
        tourScanner = { nfc: nfcReader, type: 'nfc', passive: true };
        console.log('[Passive NFC] Web NFC listening');
    } catch (e) {
        passiveTourNfcActive = false;
        updatePassiveNfcBannerState(false);
        showPassiveToast('Could not start NFC: ' + (e.message || 'permission denied'), 'danger');
    }
}

function stopPassiveTourNfc() {
    if (!passiveTourNfcActive) return;
    passiveTourNfcActive = false;
    if (tourScanner && tourScanner.passive) {
        if (tourScanner.nfc) {
            try {
                tourScanner.nfc.onreading = null;
            } catch (e) { /* ignore */ }
        }
        if (!document.getElementById('scannerModal')?.classList.contains('show')) {
            tourScanner = null;
        }
    }
    updatePassiveNfcBannerState(false);
}

async function handlePassiveTourNfcScan(scanData) {
    if (!window.GUARDPRO_ACTIVE_TOUR || scanSubmitInProgress) return;
    var scanKey = String(scanData || '').trim().toLowerCase();
    if (!scanKey) return;
    var now = Date.now();
    if (scanKey === passiveTourLastScanKey && (now - passiveTourLastScanAt) < PASSIVE_SCAN_DEBOUNCE_MS) {
        return;
    }
    passiveTourLastScanKey = scanKey;
    passiveTourLastScanAt = now;

    var checkpointId = lookupPassiveCheckpointId(scanData);
    if (!checkpointId) {
        showPassiveToast('Tag not on this patrol', 'warning');
        return;
    }
    currentTourLogId = window.GUARDPRO_ACTIVE_TOUR.tour_log_id;
    currentCheckpointId = checkpointId;
    await submitTourCheckpointScan(scanData, {
        autoMode: true,
        checkpointId: checkpointId,
    });
}

async function submitTourCheckpointScan(scanData, options) {
    options = options || {};
    if (scanSubmitInProgress) return null;
    scanSubmitInProgress = true;
    var tourLogId = options.tourLogId || currentTourLogId || (window.GUARDPRO_ACTIVE_TOUR && window.GUARDPRO_ACTIVE_TOUR.tour_log_id);
    var checkpointId = options.checkpointId || currentCheckpointId;
    try {
        var latitude = null;
        var longitude = null;
        try {
            var position = await new Promise(function(resolve, reject) {
                navigator.geolocation.getCurrentPosition(resolve, reject, {
                    enableHighAccuracy: true,
                    timeout: 5000,
                });
            });
            latitude = position.coords.latitude;
            longitude = position.coords.longitude;
        } catch (geoErr) {
            console.warn('[Tour Scan] GPS:', geoErr);
        }
        var params = {
            scan_data: scanData,
            tour_log_id: parseInt(tourLogId, 10),
        };
        if (checkpointId) {
            params.checkpoint_id = parseInt(checkpointId, 10);
        }
        if (latitude != null) params.latitude = latitude;
        if (longitude != null) params.longitude = longitude;
        var response = await fetch('/guardpro/api/checkpoint/scan', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params,
            }),
        });
        if (!response.ok) {
            throw new Error('Server error (' + response.status + ')');
        }
        var result = await response.json();
        var responseData = result.result !== undefined ? result.result : result;
        if (!responseData || !responseData.success) {
            var errMsg = (responseData && (responseData.message || responseData.error))
                || 'Scan failed';
            if (options.autoMode) {
                showPassiveToast(errMsg, 'danger');
            } else {
                showScanError(errMsg);
            }
            return null;
        }
        if (options.autoMode) {
            if ('vibrate' in navigator) {
                try { navigator.vibrate([120, 60, 120]); } catch (v) { /* ignore */ }
            }
            var cpName = responseData.checkpoint || 'Checkpoint';
            showPassiveToast(cpName + ' recorded', 'success');
        }
        var sid = responseData.scan_id;
        var st = responseData.status;
        if (responseData.already_scanned) {
            if (options.autoMode) {
                showPassiveToast((responseData.checkpoint || 'Checkpoint') + ' already scanned', 'info');
            }
            setTimeout(function() { window.location.reload(); }, options.autoMode ? 800 : 700);
        } else if (sid && st !== 'failed') {
            pendingCheckpointScanId = sid;
            currentTourLogId = tourLogId;
            stopPassiveTourNfc();
            openEvidenceModalForScan(sid, responseData.message || 'Checkpoint recorded.');
        } else {
            setTimeout(function() { window.location.reload(); }, 900);
        }
        return responseData;
    } catch (e) {
        console.error('[Tour Scan] submit error:', e);
        if (options.autoMode) {
            showPassiveToast(e.message || 'Failed to save scan', 'danger');
        } else {
            showScanError(e.message || 'Failed to submit scan');
        }
        return null;
    } finally {
        scanSubmitInProgress = false;
    }
}

function openEvidenceModalForScan(scanId, message) {
    var modalEl = document.getElementById('scannerModal');
    if (!modalEl) {
        window.location.reload();
        return;
    }
    showPostScanEvidenceStep(scanId, message);
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        bootstrap.Modal.getOrCreateInstance(modalEl).show();
    } else {
        modalEl.classList.add('show');
        modalEl.style.display = 'block';
    }
}

function initPassiveTourAutoScan() {
    if (!window.GUARDPRO_ACTIVE_TOUR) return;
    passiveTourScanLookup = buildPassiveTourScanLookup(window.GUARDPRO_ACTIVE_TOUR);
    var enableBtn = document.getElementById('passiveNfcEnableBtn');
    if (enableBtn) {
        enableBtn.addEventListener('click', function() {
            startPassiveTourNfc();
        });
    }
    updatePassiveNfcBannerState(false);
    var isNative = window.isNativeApp || (typeof AndroidBridge !== 'undefined');
    if (isNative) {
        startPassiveTourNfc();
    }
}

// Handle modal shown event (Bootstrap 5 event)
document.addEventListener('DOMContentLoaded', function() {
    bindPostScanFileInputs();
    initPassiveTourAutoScan();
    const modalEl = document.getElementById('scannerModal');
    if (modalEl) {
        modalEl.addEventListener('shown.bs.modal', function() {
            console.log('[Guard Pro Tours] Scanner modal opened');
            // Start scanning based on current scan type
            const modeToggle = document.getElementById('scannerModeToggle');
            if (currentScanType === 'both') {
                modeToggle.style.display = 'flex';
                startQRScanner(); // Default to QR
            } else if (currentScanType === 'qr') {
                modeToggle.style.display = 'none';
                startQRScanner();
            } else if (currentScanType === 'nfc') {
                modeToggle.style.display = 'none';
                startNFCScanner();
            }
        });

        modalEl.addEventListener('hidden.bs.modal', function() {
            console.log('[Guard Pro Tours] Scanner modal closed');
            stopScanning();
            pendingCheckpointScanId = null;
            if (window.GUARDPRO_ACTIVE_TOUR) {
                startPassiveTourNfc();
            }
            document.getElementById('scanResult').style.display = 'none';
            document.getElementById('manualCodeInput').value = '';
            const evPanel = document.getElementById('postScanEvidencePanel');
            if (evPanel) evPanel.style.display = 'none';
            const pPh = document.getElementById('postScanPhotos');
            const pVid = document.getElementById('postScanVideos');
            const pObs = document.getElementById('postScanObservations');
            const pErr = document.getElementById('postScanEvidenceError');
            if (pPh) pPh.value = '';
            if (pVid) pVid.value = '';
            if (pObs) pObs.value = '';
            var pIssueChk = document.getElementById('postScanReportFacilityIssue');
            var pIssueType = document.getElementById('postScanFacilityIssueType');
            var pIssueDesc = document.getElementById('postScanIssueDescription');
            var pIssueFields = document.getElementById('postScanFacilityIssueFields');
            if (pIssueChk) pIssueChk.checked = false;
            if (pIssueType) pIssueType.value = '';
            if (pIssueDesc) pIssueDesc.value = '';
            if (pIssueFields) pIssueFields.style.display = 'none';
            var pPhList = document.getElementById('postScanPhotosList');
            var pVidList = document.getElementById('postScanVideosList');
            if (pPhList) pPhList.textContent = '';
            if (pVidList) pVidList.textContent = '';
            if (pErr) { pErr.style.display = 'none'; pErr.textContent = ''; }
            const titleEl = document.getElementById('scannerModalTitle');
            if (titleEl) titleEl.textContent = 'Scan Checkpoint';
        });
    }
});

function openScanner(btn) {
    pendingCheckpointScanId = null;
    const evPanel0 = document.getElementById('postScanEvidencePanel');
    if (evPanel0) evPanel0.style.display = 'none';
    const title0 = document.getElementById('scannerModalTitle');
    if (title0) title0.textContent = 'Scan Checkpoint';
    // Store checkpoint data for when modal opens
    currentCheckpointId = btn.dataset.checkpointId;
    currentTourLogId = btn.dataset.tourLogId;
    currentScanType = btn.dataset.scanType || 'qr';
    console.log('[Guard Pro Tours] Opening scanner for checkpoint:', currentCheckpointId, 'Mode:', currentScanType);

    // CRITICAL: Call startNFCScanner immediately on user click to preserve User Gesture context
    // This prevents 'NFC Permission request denied' errors in many browsers
    if (currentScanType === 'nfc' || currentScanType === 'both') {
        // Start NFC in background before modal animation finishes
        startNFCScanner().catch(e => console.warn('Delayed NFC start failed:', e));
    }

    // Ensure Bootstrap modal is properly initialized and shown
    const modalEl = document.getElementById('scannerModal');
    if (modalEl) {
        // Use Bootstrap 5 modal API
        if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
            const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
            modal.show();
        } else {
            // Fallback: manually show modal if Bootstrap not loaded
            console.warn('[Guard Pro Tours] Bootstrap not found, using fallback');
            modalEl.classList.add('show');
            modalEl.style.display = 'block';
            modalEl.setAttribute('aria-hidden', 'false');
            document.body.classList.add('modal-open');
            const backdrop = document.createElement('div');
            backdrop.className = 'modal-backdrop fade show';
            backdrop.id = 'scannerModalBackdrop';
            document.body.appendChild(backdrop);
        }
    } else {
        console.error('[Guard Pro Tours] Scanner modal element not found');
    }
}

async function markWalkaroundCheckpoint(btn) {
    if (!btn || scanSubmitInProgress) return;
    currentCheckpointId = btn.dataset.checkpointId;
    currentTourLogId = btn.dataset.tourLogId;
    btn.disabled = true;
    try {
        await submitTourCheckpointScan('walkaround', {
            autoMode: true,
            checkpointId: currentCheckpointId,
            tourLogId: currentTourLogId,
        });
    } finally {
        btn.disabled = false;
    }
}

function switchScanMode(mode) {
    stopScanning();

    // Update button states
    document.querySelectorAll('#scannerModeToggle .btn').forEach(btn => {
        btn.classList.remove('active');
    });
    event.target.closest('.btn').classList.add('active');

    if (mode === 'qr') {
        startQRScanner();
    } else {
        startNFCScanner();
    }
}

async function startQRScanner() {
    document.getElementById('qrScannerContainer').style.display = 'block';
    document.getElementById('nfcScannerContainer').style.display = 'none';

    try {
        if (!window.Html5Qrcode) {
            await new Promise((resolve) => setTimeout(resolve, 1000)); // Wait for library to load
        }

        tourScanner = new Html5Qrcode("qr-reader");

        const config = {
            fps: 10,
            qrbox: { width: 250, height: 250 },
            aspectRatio: 1.0
        };

        await tourScanner.start(
            { facingMode: "environment" },
            config,
            (decodedText) => {
                handleScanSuccess(decodedText, 'qr');
            },
            (errorMessage) => {
                // Ignore common scanning errors
            }
        );
    } catch (error) {
        console.error('QR Scanner error:', error);
        showScanError('Failed to start camera: ' + error.message);
    }
}

function guardproExtractNdefText(message) {
    if (window.guardproExtractNdefText) {
        return window.guardproExtractNdefText(message);
    }
    return '';
}
function guardproResolveNfcScanPayload(ndefText, serialNumber) {
    if (window.guardproResolveNfcScanPayload && window.guardproResolveNfcScanPayload !== guardproResolveNfcScanPayload) {
        return window.guardproResolveNfcScanPayload(ndefText, serialNumber);
    }
    var serial = (serialNumber && String(serialNumber).trim()) || '';
    if (serial) {
        var hex = serial.replace(/[^0-9a-fA-F]/g, '').toLowerCase();
        var pairs = hex.match(/.{1,2}/g) || [];
        return pairs.join(':');
    }
    return (ndefText && String(ndefText).trim()) || '';
}

// Global bridge for Native NFC (Called from TwaLauncherActivity.kt)
window.onNativeNFCScan = function(tagData, serial) {
    console.log('[Guard Pro Tours] NFC Tag scanned via Native Bridge:', tagData, serial);
    var scanPayload = typeof guardproResolveNfcScanPayload === 'function'
        ? guardproResolveNfcScanPayload(tagData, serial)
        : (serial || tagData);
    if (passiveTourNfcActive && window.GUARDPRO_ACTIVE_TOUR) {
        handlePassiveTourNfcScan(scanPayload);
        return;
    }
    var nfcContainer = document.getElementById('nfcScannerContainer');
    var modalEl = document.getElementById('scannerModal');
    if (nfcContainer && nfcContainer.style.display === 'block' &&
        modalEl && modalEl.classList.contains('show')) {
        if (typeof handleScanSuccess === 'function') {
            handleScanSuccess(scanPayload, 'nfc');
        }
    }
};

async function startNFCScanner() {
    const nfcContainer = document.getElementById('nfcScannerContainer');
    const qrContainer = document.getElementById('qrScannerContainer');
    if (nfcContainer) nfcContainer.style.display = 'block';
    if (qrContainer) qrContainer.style.display = 'none';

    try {
        const isNative = window.isNativeApp || (typeof AndroidBridge !== 'undefined');

        if (!('NDEFReader' in window)) {
            if (isNative) {
                console.log('[Guard Pro Tours] Web NFC API unavailable, using Native Bridge');
                tourScanner = { type: 'nfc', native: true };
                return;
            }
            throw new Error('Web NFC is not supported on this device or browser. Please use Chrome on Android.');
        }

        // Use existing scanner if available
        if (tourScanner && tourScanner.type === 'nfc' && (tourScanner.initializing || tourScanner.nfc || tourScanner.native)) {
            console.log('[Guard Pro Tours] NFC scanner already active or initializing');
            return;
        }

        console.log('[Guard Pro Tours] Starting NFC scan (checking permissions)...');
        tourScanner = { type: 'nfc', initializing: true };
        const nfcReader = new NDEFReader();

        try {
            // This call must be triggered by a user gesture
            await nfcReader.scan();
        } catch (e) {
            if (isNative) {
                console.warn('[Guard Pro Tours] Web NFC scan failed in native app, falling back to Bridge:', e);
                tourScanner = { type: 'nfc', native: true };
                return;
            }
            tourScanner = null; // Reset so user can try again
            throw e;
        }

        console.log('[Guard Pro Tours] Web NFC scan started successfully');

        nfcReader.onreading = ({ message, serialNumber }) => {
            console.log('[NFC Scan] Serial number:', serialNumber);
            console.log('[NFC Scan] Message records:', message?.records?.length || 0);
            const ndefText = guardproExtractNdefText(message);
            const tagDataStr = guardproResolveNfcScanPayload(ndefText, serialNumber);
            console.log('[NFC Scan] Final tag data to send:', tagDataStr);
            if (tagDataStr) {
                handleScanSuccess(tagDataStr, 'nfc');
            } else {
                console.error('[NFC Scan] Invalid tag data:', tagData);
                showScanError('Could not read NFC tag data. Please try again.');
            }
        };

        nfcReader.addEventListener('readingerror', () => {
            showScanError('NFC reading error. Please try again.');
        });

        tourScanner = { nfc: nfcReader, type: 'nfc' };
    } catch (error) {
        console.error('NFC Scanner error:', error);
        showScanError(error.message);
    }
}

async function stopScanning() {
    console.log('[Guard Pro Tours] Stopping scanner...');
    if (tourScanner) {
        try {
            // Handle QR scanner (Html5Qrcode)
            if (tourScanner.stop && typeof tourScanner.stop === 'function') {
                console.log('[Guard Pro Tours] Stopping QR scanner...');
                await tourScanner.stop();
                if (tourScanner.clear && typeof tourScanner.clear === 'function') {
                    tourScanner.clear();
                }
            }
            // Handle NFC scanner (wrapped in object)
            else if (tourScanner.type === 'nfc' && tourScanner.nfc) {
                console.log('[Guard Pro Tours] NFC scanner detected, no stop needed');
                // NFC scanner doesn't have an explicit stop method
                // It will stop when we set tourScanner to null
            }
        } catch (error) {
            console.error('[Guard Pro Tours] Error stopping scanner:', error);
        }
        tourScanner = null;
        console.log('[Guard Pro Tours] Scanner stopped and cleared');
    }

    // Hide scanner containers
    const qrContainer = document.getElementById('qrScannerContainer');
    const nfcContainer = document.getElementById('nfcScannerContainer');
    if (qrContainer) qrContainer.style.display = 'none';
    if (nfcContainer) nfcContainer.style.display = 'none';
}

function closeModalAndReload() {
    const modalEl = document.getElementById('scannerModal');
    if (!modalEl) {
        window.location.reload(true);
        return;
    }
    const onHidden = function() {
        modalEl.removeEventListener('hidden.bs.modal', onHidden);
        window.location.reload(true);
    };
    modalEl.addEventListener('hidden.bs.modal', onHidden, { once: true });
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        bootstrap.Modal.getOrCreateInstance(modalEl).hide();
    } else {
        window.location.reload(true);
    }
}

function showPostScanEvidenceStep(scanId, message) {
    pendingCheckpointScanId = scanId;
    const modeToggle = document.getElementById('scannerModeToggle');
    if (modeToggle) modeToggle.style.display = 'none';
    document.getElementById('qrScannerContainer').style.display = 'none';
    document.getElementById('nfcScannerContainer').style.display = 'none';
    document.getElementById('manualInputContainer').style.display = 'none';
    document.getElementById('scanResult').style.display = 'none';
    const titleEl = document.getElementById('scannerModalTitle');
    if (titleEl) titleEl.textContent = 'Add findings (optional)';
    const msgEl = document.getElementById('postScanSuccessMsg');
    if (msgEl) msgEl.textContent = message || 'Checkpoint recorded.';
    const errEl = document.getElementById('postScanEvidenceError');
    if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
    const successPanel = document.getElementById('postScanSaveSuccessPanel');
    if (successPanel) successPanel.style.display = 'none';
    document.getElementById('postScanEvidencePanel').style.display = 'block';
    bindPostScanFileInputs();
    updatePostScanFileList('postScanPhotos', 'postScanPhotosList');
    updatePostScanFileList('postScanVideos', 'postScanVideosList');
}

function skipPostScanEvidence() {
    closeModalAndReload();
}

function continueAfterPostScanSave() {
    closeModalAndReload();
}

function buildPostScanSaveSummaryItems() {
    var items = [];
    var obs = (document.getElementById('postScanObservations') || {}).value || '';
    obs = obs.trim();
    if (obs) {
        var shortObs = obs.length > 72 ? obs.substring(0, 72) + '…' : obs;
        items.push({ icon: 'fa-sticky-note-o', text: 'Notes: ' + shortObs });
    }
    var photosIn = document.getElementById('postScanPhotos');
    var videosIn = document.getElementById('postScanVideos');
    var photoCount = photosIn && photosIn.files ? photosIn.files.length : 0;
    var videoCount = videosIn && videosIn.files ? videosIn.files.length : 0;
    if (photoCount) {
        items.push({
            icon: 'fa-camera',
            text: photoCount === 1 ? '1 photo attached' : photoCount + ' photos attached',
        });
    }
    if (videoCount) {
        items.push({
            icon: 'fa-video-camera',
            text: videoCount === 1 ? '1 video attached' : videoCount + ' videos attached',
        });
    }
    var issueChk = document.getElementById('postScanReportFacilityIssue');
    if (issueChk && issueChk.checked) {
        var typeSel = document.getElementById('postScanFacilityIssueType');
        var typeLabel = typeSel && typeSel.selectedIndex > 0
            ? typeSel.options[typeSel.selectedIndex].text
            : 'Facility issue';
        items.push({ icon: 'fa-building-o', text: 'Reported: ' + typeLabel });
    }
    return items;
}

function showPostScanSaveSuccess(responseData) {
    responseData = responseData || {};
    var formPanel = document.getElementById('postScanEvidencePanel');
    var successPanel = document.getElementById('postScanSaveSuccessPanel');
    if (formPanel) formPanel.style.display = 'none';
    if (!successPanel) {
        closeModalAndReload();
        return;
    }
    var isWarning = !!responseData.warning;
    var hero = document.getElementById('postScanSaveSuccessHero');
    var iconEl = document.getElementById('postScanSaveSuccessIcon');
    var titleEl = document.getElementById('postScanSaveSuccessTitle');
    var msgEl = document.getElementById('postScanSaveSuccessMessage');
    var badge = document.getElementById('postScanSaveSuccessBadge');
    var incidentEl = document.getElementById('postScanSaveSuccessIncident');
    var summaryEl = document.getElementById('postScanSaveSuccessSummary');
    var modalTitle = document.getElementById('scannerModalTitle');
    if (modalTitle) {
        modalTitle.textContent = isWarning ? 'Saved with notice' : 'Findings saved';
    }
    if (hero) {
        hero.className = 'post-scan-save-success__hero ' + (
            isWarning
                ? 'post-scan-save-success__hero--warning'
                : 'post-scan-save-success__hero--success'
        );
    }
    if (iconEl) {
        iconEl.className = isWarning ? 'fa fa-exclamation' : 'fa fa-check';
    }
    if (titleEl) {
        titleEl.textContent = isWarning ? 'Saved with a notice' : 'Findings saved';
    }
    if (msgEl) {
        msgEl.textContent = responseData.message || (
            isWarning
                ? 'Your notes and photos were saved. Review the notice below.'
                : 'Your checkpoint findings were recorded successfully.'
        );
    }
    var incidentName = responseData.facility_incident_name || '';
    if (incidentName && badge && incidentEl) {
        badge.style.display = 'flex';
        incidentEl.textContent = incidentName;
    } else if (badge) {
        badge.style.display = 'none';
    }
    var summaryItems = buildPostScanSaveSummaryItems();
    if (summaryEl) {
        if (summaryItems.length) {
            summaryEl.innerHTML = summaryItems.map(function(item) {
                return '<li><i class="fa ' + item.icon + '"></i><span>' +
                    item.text.replace(/</g, '&lt;').replace(/>/g, '&gt;') +
                    '</span></li>';
            }).join('');
            summaryEl.style.display = 'block';
        } else {
            summaryEl.style.display = 'none';
            summaryEl.innerHTML = '';
        }
    }
    successPanel.style.display = 'block';
    var modalBody = successPanel.closest('.modal-body');
    if (modalBody) modalBody.scrollTop = 0;
}

var POST_SCAN_MAX_IMAGE_DIM = 1200;
var POST_SCAN_JPEG_QUALITY = 0.85;
var POST_SCAN_MAX_VIDEO_BYTES = 80 * 1024 * 1024;

function triggerPostScanFilePick(inputId) {
    var input = document.getElementById(inputId);
    if (!input) {
        console.warn('[Guard Pro Tours] File input not found:', inputId);
        return;
    }
    try {
        input.value = '';
    } catch (e) { /* ignore */ }
    input.click();
}

function formatPostScanFileSize(bytes) {
    if (!bytes || bytes < 1024) {
        return (bytes || 0) + ' B';
    }
    if (bytes < 1024 * 1024) {
        return (bytes / 1024).toFixed(1) + ' KB';
    }
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function updatePostScanFileList(inputId, listId) {
    var input = document.getElementById(inputId);
    var listEl = document.getElementById(listId);
    if (!input || !listEl) {
        return;
    }
    if (!input.files || !input.files.length) {
        listEl.textContent = 'No files selected';
        return;
    }
    var parts = [];
    for (var i = 0; i < input.files.length; i++) {
        var f = input.files[i];
        parts.push(f.name + ' (' + formatPostScanFileSize(f.size) + ')');
    }
    listEl.textContent = parts.join(', ');
}

function bindPostScanFileInputs() {
    var photoIn = document.getElementById('postScanPhotos');
    var videoIn = document.getElementById('postScanVideos');
    if (photoIn && !photoIn.dataset.bound) {
        photoIn.dataset.bound = '1';
        photoIn.addEventListener('change', function() {
            updatePostScanFileList('postScanPhotos', 'postScanPhotosList');
        });
    }
    if (videoIn && !videoIn.dataset.bound) {
        videoIn.dataset.bound = '1';
        videoIn.addEventListener('change', function() {
            updatePostScanFileList('postScanVideos', 'postScanVideosList');
        });
    }
}

function compressImageFileForUpload(file) {
    return new Promise(function(resolve, reject) {
        if (!file || !file.type || file.type.indexOf('image/') !== 0) {
            fileToBase64Payload(file).then(resolve).catch(reject);
            return;
        }
        var url = URL.createObjectURL(file);
        var img = new Image();
        img.onload = function() {
            URL.revokeObjectURL(url);
            var maxDim = POST_SCAN_MAX_IMAGE_DIM;
            var w = img.naturalWidth || img.width;
            var h = img.naturalHeight || img.height;
            if (w > maxDim || h > maxDim) {
                var ratio = Math.min(maxDim / w, maxDim / h);
                w = Math.round(w * ratio);
                h = Math.round(h * ratio);
            }
            var canvas = document.createElement('canvas');
            canvas.width = w;
            canvas.height = h;
            var ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, w, h);
            canvas.toBlob(function(blob) {
                if (!blob) {
                    fileToBase64Payload(file).then(resolve).catch(reject);
                    return;
                }
                var reader = new FileReader();
                reader.onload = function() {
                    var res = reader.result;
                    var comma = res.indexOf(',');
                    var base64 = comma >= 0 ? res.substring(comma + 1) : res;
                    var baseName = (file.name || 'photo').replace(/\.[^.]+$/, '');
                    resolve({
                        name: baseName + '.jpg',
                        data: base64,
                        mimetype: 'image/jpeg'
                    });
                };
                reader.onerror = function() {
                    fileToBase64Payload(file).then(resolve).catch(reject);
                };
                reader.readAsDataURL(blob);
            }, 'image/jpeg', POST_SCAN_JPEG_QUALITY);
        };
        img.onerror = function() {
            URL.revokeObjectURL(url);
            fileToBase64Payload(file).then(resolve).catch(reject);
        };
        img.src = url;
    });
}

function fileToBase64Payload(file) {
    return new Promise(function(resolve, reject) {
        var reader = new FileReader();
        reader.onload = function() {
            var res = reader.result;
            var comma = res.indexOf(',');
            var base64 = comma >= 0 ? res.substring(comma + 1) : res;
            resolve({
                name: file.name,
                data: base64,
                mimetype: file.type || 'application/octet-stream'
            });
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

function togglePostScanFacilityIssue() {
    var chk = document.getElementById('postScanReportFacilityIssue');
    var box = document.getElementById('postScanFacilityIssueFields');
    if (box) {
        box.style.display = (chk && chk.checked) ? 'block' : 'none';
    }
}

function getPostScanFacilityIssueParams() {
    var chk = document.getElementById('postScanReportFacilityIssue');
    if (!chk || !chk.checked) {
        return {};
    }
    var typeEl = document.getElementById('postScanFacilityIssueType');
    var descEl = document.getElementById('postScanIssueDescription');
    var issueType = typeEl ? typeEl.value : '';
    var issueDesc = descEl ? descEl.value.trim() : '';
    if (!issueType) {
        throw new Error('Please select a facility issue type.');
    }
    if (!issueDesc || issueDesc.length < 10) {
        throw new Error('Please describe the facility issue (at least 10 characters).');
    }
    return {
        issues_found: true,
        facility_issue_type: issueType,
        issue_description: issueDesc,
    };
}

function parseEvidenceApiResponse(httpResponse, jsonBody) {
    if (jsonBody && jsonBody.error) {
        var errData = jsonBody.error.data || {};
        var msg = errData.message || jsonBody.error.message || 'Server error';
        if (Array.isArray(msg)) {
            msg = msg.join('\n');
        }
        throw new Error(msg);
    }
    var data = (jsonBody && jsonBody.result !== undefined) ? jsonBody.result : jsonBody;
    if (!httpResponse.ok) {
        throw new Error('Server error (' + httpResponse.status + '). Try again.');
    }
    if (!data || data.success === false) {
        throw new Error(
            (data && (data.message || data.error)) || 'Could not save findings'
        );
    }
    return data;
}

async function submitPostScanEvidence() {
    if (!pendingCheckpointScanId) {
        skipPostScanEvidence();
        return;
    }
    var btn = document.getElementById('postScanEvidenceSubmitBtn');
    var errEl = document.getElementById('postScanEvidenceError');
    if (btn) btn.disabled = true;
    if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
    try {
        var photosIn = document.getElementById('postScanPhotos').files;
        var videosIn = document.getElementById('postScanVideos').files;
        var obs = document.getElementById('postScanObservations').value.trim();
        var issueChk = document.getElementById('postScanReportFacilityIssue');
        var reportIssue = issueChk && issueChk.checked;
        var issueParams = reportIssue ? getPostScanFacilityIssueParams() : {};
        var photos = [];
        var videos = [];
        var i;
        for (i = 0; i < photosIn.length; i++) {
            var pf = photosIn[i];
            var mt = (pf.type || '').toLowerCase();
            if (mt.indexOf('heic') >= 0 || mt.indexOf('heif') >= 0 ||
                /\.heic$/i.test(pf.name) || /\.heif$/i.test(pf.name)) {
                throw new Error(
                    'Photo "' + pf.name + '" is HEIC format. On iPhone: Settings → Camera → Formats → Most Compatible, then take the photo again.'
                );
            }
            photos.push(await compressImageFileForUpload(pf));
        }
        for (i = 0; i < videosIn.length; i++) {
            var vf = videosIn[i];
            if (vf.size > POST_SCAN_MAX_VIDEO_BYTES) {
                throw new Error(
                    'Video "' + vf.name + '" is too large (' +
                    formatPostScanFileSize(vf.size) +
                    '). Please use a shorter clip or lower resolution (max ~80 MB).'
                );
            }
            videos.push(await fileToBase64Payload(vf));
        }
        if (!photos.length && !videos.length && !obs && !reportIssue) {
            skipPostScanEvidence();
            return;
        }
        var params = {
            scan_id: pendingCheckpointScanId,
            issues_found: reportIssue,
        };
        if (obs) {
            params.observations = obs;
        }
        if (photos.length) {
            params.photos = photos;
        }
        if (videos.length) {
            params.videos = videos;
        }
        if (reportIssue) {
            params.facility_issue_type = issueParams.facility_issue_type;
            params.issue_description = issueParams.issue_description;
        }
        var response = await fetch('/guardpro/api/checkpoint/scan/evidence', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params,
            }),
        });
        var result = await response.json();
        var responseData = parseEvidenceApiResponse(response, result);
        showPostScanSaveSuccess(responseData);
    } catch (e) {
        console.error('[Guard Pro Tours] Evidence submit error:', e);
        if (errEl) {
            errEl.textContent = e.message || 'Failed to save. You can skip and try again from the back office.';
            errEl.style.display = 'block';
        }
    } finally {
        if (btn) btn.disabled = false;
    }
}

async function handleScanSuccess(scanData, scanType) {
    if (scanSubmitInProgress) {
        console.log('[Guard Pro Tours] Scan already in progress, ignoring duplicate read');
        return;
    }
    scanSubmitInProgress = true;
    try {
    await stopScanning();

    // Validate scan data
    if (!scanData || (typeof scanData !== 'string' && typeof scanData !== 'number')) {
        console.error('[Guard Pro Tours] Invalid scan data:', scanData);
        showScanError('Invalid scan data. Please try scanning again.');
        return;
    }

    // Convert to string and trim
    scanData = String(scanData).trim();

    if (!scanData) {
        console.error('[Guard Pro Tours] Empty scan data after conversion');
        showScanError('Could not read scan data. Please try scanning again.');
        return;
    }

    console.log('[Guard Pro Tours] Processing scan:', scanData, 'for checkpoint:', currentCheckpointId, 'tour log:', currentTourLogId);

    // Get GPS location
    let latitude = null;
    let longitude = null;

    try {
        const position = await new Promise((resolve, reject) => {
            navigator.geolocation.getCurrentPosition(resolve, reject, {
                enableHighAccuracy: true,
                timeout: 5000
            });
        });
        latitude = position.coords.latitude;
        longitude = position.coords.longitude;
        console.log('[Guard Pro Tours] GPS location obtained:', latitude, longitude);
    } catch (error) {
        console.warn('[Guard Pro Tours] GPS error:', error);
    }

    // Submit scan via JSON-RPC
    try {
        const response = await fetch('/guardpro/api/checkpoint/scan', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    checkpoint_id: parseInt(currentCheckpointId),
                    scan_data: scanData,
                    latitude: latitude,
                    longitude: longitude,
                    tour_log_id: parseInt(currentTourLogId)
                }
            })
        });

        if (!response.ok) {
            console.error('[Guard Pro Tours] HTTP error:', response.status, response.statusText);
            showScanError(`Server error (${response.status}). Please try again.`);
            return;
        }

        const result = await response.json();
        console.log('[Guard Pro Tours] Scan API response:', result);

        // Handle JSON-RPC response format - check both result.result and result directly
        const responseData = result.result !== undefined ? result.result : result;

        if (!responseData) {
            console.error('[Guard Pro Tours] No response data received. Full result:', result);
            showScanError('No response from server. Please try again.');
            return;
        }

        if (responseData.success) {
            console.log('[Guard Pro Tours] Scan SUCCESS - Status:', responseData.status);
            showScanSuccess(responseData.message || 'Checkpoint scanned successfully!');
            await stopScanning();
            const sid = responseData.scan_id;
            const st = responseData.status;
            if (responseData.already_scanned) {
                setTimeout(function() { closeModalAndReload(); }, 700);
            } else if (sid && st !== 'failed') {
                pendingCheckpointScanId = sid;
                setTimeout(function() {
                    showPostScanEvidenceStep(sid, responseData.message || 'Checkpoint recorded.');
                }, 1100);
            } else {
                setTimeout(function() { closeModalAndReload(); }, 1200);
            }
        } else {
            const errorMsg = responseData.message || responseData.error || result.error || 'Scan failed. Please try again.';
            console.error('[Guard Pro Tours] Scan FAILED:', errorMsg, 'Full response:', responseData);
            showScanError(errorMsg);

            // Auto-close modal after showing error for 2 seconds
            setTimeout(() => {
                console.log('[Guard Pro Tours] Auto-closing modal after error...');
                const modalEl = document.getElementById('scannerModal');
                const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
                if (modal) {
                    modal.hide();
                }
            }, 2000);  // Show error message for 2 seconds before closing
        }
    } catch (error) {
        console.error('Submit scan error:', error);
        showScanError('Failed to submit scan');

        // Auto-close modal after showing error for 2 seconds
        setTimeout(() => {
            console.log('[Guard Pro Tours] Auto-closing modal after exception...');
            const modalEl = document.getElementById('scannerModal');
            const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
            if (modal) {
                modal.hide();
            }
        }, 2000);
    }
    } finally {
        scanSubmitInProgress = false;
    }
}

function submitManualCode() {
    const input = document.getElementById('manualCodeInput');
    const code = input.value.trim();
    if (code) {
        handleScanSuccess(code, 'manual');
    }
}

function showScanSuccess(message) {
    const resultDiv = document.getElementById('scanResult');
    resultDiv.className = 'scanner-success';
    resultDiv.innerHTML = '<i class="fa fa-check-circle me-2"></i>' + message;
    resultDiv.style.display = 'block';

    // Haptic feedback (vibration)
    if ('vibrate' in navigator) {
        try {
            // Double vibration pattern: 200ms, pause 100ms, 200ms
            navigator.vibrate([200, 100, 200]);
            console.log('[GuardLink] Haptic feedback triggered');
        } catch (e) {
            console.warn('[GuardLink] Haptic feedback failed:', e);
        }
    }

    // Visual confirmation animation overlay
    const overlay = document.createElement('div');
    overlay.style.cssText = `
        position: fixed;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        z-index: 9999;
        background: rgba(40, 167, 69, 0.95);
        color: white;
        padding: 30px 40px;
        border-radius: 15px;
        box-shadow: 0 10px 40px rgba(0,0,0,0.3);
        font-size: 24px;
        font-weight: bold;
        text-align: center;
        animation: scanSuccess 0.5s ease-out;
    `;
    overlay.innerHTML = '<i class="fa fa-check-circle" style="font-size: 48px; display: block; margin-bottom: 10px;"></i>Scan Successful!';
    document.body.appendChild(overlay);

    // Add CSS animation if not already present
    if (!document.getElementById('scanSuccessStyle')) {
        const style = document.createElement('style');
        style.id = 'scanSuccessStyle';
        style.textContent = `
            @keyframes scanSuccess {
                0% { transform: translate(-50%, -50%) scale(0.5); opacity: 0; }
                50% { transform: translate(-50%, -50%) scale(1.1); }
                100% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
            }
        `;
        document.head.appendChild(style);
    }

    // Remove overlay after 1 second
    setTimeout(() => {
        overlay.style.transition = 'opacity 0.3s';
        overlay.style.opacity = '0';
        setTimeout(() => overlay.remove(), 300);
    }, 1000);

    // Optional audio beep (check if user has sound enabled in localStorage)
    const soundEnabled = localStorage.getItem('scan_sound_enabled') !== 'false'; // Default: true
    if (soundEnabled) {
        try {
            // Create a short beep sound using Web Audio API
            const audioContext = new (window.AudioContext || window.webkitAudioContext)();
            const oscillator = audioContext.createOscillator();
            const gainNode = audioContext.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(audioContext.destination);

            oscillator.frequency.value = 800; // 800 Hz tone
            oscillator.type = 'sine';

            gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.2);

            oscillator.start(audioContext.currentTime);
            oscillator.stop(audioContext.currentTime + 0.2);

            console.log('[GuardLink] Audio beep played');
        } catch (e) {
            console.warn('[GuardLink] Audio beep failed:', e);
        }
    }
}

function showScanError(message) {
    const resultDiv = document.getElementById('scanResult');
    resultDiv.className = 'scanner-error';
    resultDiv.innerHTML = '<i class="fa fa-exclamation-circle me-2"></i>' + message;
    resultDiv.style.display = 'block';
}

let pendingStartTourBtn = null;
let blockedPatrolTourLogId = null;
let partialCompleteTourLogId = null;

function showBsModal(modalId) {
    const modalEl = document.getElementById(modalId);
    if (!modalEl) {
        console.error('[Guard Pro Tours] Modal not found:', modalId);
        return;
    }
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        bootstrap.Modal.getOrCreateInstance(modalEl).show();
        return;
    }
    if (typeof $ !== 'undefined' && typeof $(modalEl).modal === 'function') {
        $(modalEl).modal('show');
        return;
    }
    modalEl.classList.add('show');
    modalEl.style.display = 'block';
    modalEl.setAttribute('aria-hidden', 'false');
    document.body.classList.add('modal-open');
}

function hideBsModal(modalId) {
    const modalEl = document.getElementById(modalId);
    if (!modalEl) {
        return;
    }
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        const inst = bootstrap.Modal.getInstance(modalEl);
        if (inst) {
            inst.hide();
        } else {
            bootstrap.Modal.getOrCreateInstance(modalEl).hide();
        }
        return;
    }
    if (typeof $ !== 'undefined' && typeof $(modalEl).modal === 'function') {
        $(modalEl).modal('hide');
        return;
    }
    modalEl.classList.remove('show');
    modalEl.style.display = 'none';
    modalEl.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('modal-open');
}

function showBlockedTourModal(message, blockingTours, pendingBtn) {
    pendingStartTourBtn = pendingBtn || null;
    blockedPatrolTourLogId = blockingTours && blockingTours.length
        ? blockingTours[0].tour_log_id
        : null;
    const msgEl = document.getElementById('blockedTourModalMessage');
    const listEl = document.getElementById('blockedTourModalList');
    if (msgEl) {
        msgEl.textContent = message || 'Finish your current patrol before starting another.';
    }
    if (listEl) {
        listEl.innerHTML = '';
        (blockingTours || []).forEach(function (t) {
            const pct = t.completion_percentage != null
                ? Math.round(t.completion_percentage * 100)
                : 0;
            const item = document.createElement('div');
            item.className = 'list-group-item';
            item.innerHTML =
                '<strong>' + (t.tour_name || 'Patrol') + '</strong><br/>' +
                '<small class="text-muted">' +
                (t.scanned_checkpoints || 0) + '/' + (t.expected_checkpoints || 0) +
                ' checkpoints (' + pct + '%)</small>';
            listEl.appendChild(item);
        });
    }
    showBsModal('blockedTourModal');
}

function continueBlockedPatrol() {
    hideBsModal('blockedTourModal');
    if (blockedPatrolTourLogId) {
        const card = document.getElementById('tour-card-' + blockedPatrolTourLogId);
        if (card) {
            card.scrollIntoView({ behavior: 'smooth', block: 'start' });
            card.classList.add('border', 'border-primary');
            setTimeout(function () {
                card.classList.remove('border', 'border-primary');
            }, 2500);
        }
    }
}

function endBlockedPatrolAndRetry() {
    if (!blockedPatrolTourLogId) {
        return;
    }
    hideBsModal('blockedTourModal');
    partialCompleteTourLogId = blockedPatrolTourLogId;
    document.getElementById('partialCompletionReason').value = '';
    showBsModal('partialCompleteModal');
}

async function startTour(btn) {
    const tourId = parseInt(btn.dataset.tourId, 10);
    const shiftId = btn.dataset.shiftId ? parseInt(btn.dataset.shiftId, 10) : null;
    const origHtml = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<i class="fa fa-spinner fa-spin me-1"></i>Starting...';

    try {
        const params = { tour_id: tourId };
        if (shiftId) {
            params.shift_id = shiftId;
        }
        const response = await fetch('/guardpro/api/tour/start', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params,
            }),
        });
        const result = await response.json();
        const data = result.result || {};

        if (data.success) {
            if (data.resumed) {
                alert(data.message || 'Continuing your patrol.');
            }
            window.location.reload();
            return;
        }
        if (data.error === 'active_tour_exists') {
            showBlockedTourModal(
                data.message,
                data.blocking_tours,
                btn
            );
            return;
        }
        alert(data.error || data.message || 'Failed to start tour');
    } catch (error) {
        console.error('Start tour error:', error);
        alert('Failed to start tour');
    } finally {
        btn.disabled = false;
        btn.innerHTML = origHtml;
    }
}

let completeTourLogId = null;

function showCompleteTourModal(btn) {
    completeTourLogId = parseInt(btn.dataset.tourLogId, 10);
    const obs = document.getElementById('completeTourObservations');
    const iss = document.getElementById('completeTourIssues');
    if (obs) obs.value = '';
    if (iss) iss.value = '';
    showBsModal('completeTourModal');
}

async function confirmCompleteTour() {
    const tourLogId = completeTourLogId;
    if (!tourLogId) {
        return;
    }
    const obsEl = document.getElementById('completeTourObservations');
    const issEl = document.getElementById('completeTourIssues');
    const observations = obsEl ? obsEl.value.trim() : '';
    const issuesFound = issEl ? issEl.value.trim() : '';
    const confirmBtn = document.getElementById('confirmCompleteTourBtn');
    if (confirmBtn) {
        confirmBtn.disabled = true;
        confirmBtn.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i>Completing...';
    }
    try {
        const response = await fetch('/guardpro/api/tour/complete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    tour_log_id: tourLogId,
                    partial: false,
                    observations: observations || undefined,
                    issues_found: issuesFound || undefined,
                }
            })
        });
        const result = await response.json();
        if (result.result && result.result.success) {
            hideBsModal('completeTourModal');
            const logId = result.result.tour_log_id || tourLogId;
            window.location.href = '/guardpro/mobile/tours/summary/' + logId;
            return;
        }
        if (result.result?.checkpoint_status) {
            const status = result.result.checkpoint_status;
            alert(
                'Cannot complete tour!\n\nYou must scan all checkpoints first:\n\n' +
                'Scanned: ' + status.scanned + '/' + status.expected + '\n' +
                'Missing: ' + status.missing + '\n' +
                'Progress: ' + (status.completion_percentage * 100).toFixed(1) + '%'
            );
        } else if (result.result?.pending_tasks && result.result.pending_tasks.length > 0) {
            const taskList = result.result.pending_tasks
                .map(function (task) { return '• ' + task.name + ' (' + task.state + ')'; })
                .join('\n');
            alert('Cannot complete tour!\n\nComplete these tasks first:\n\n' + taskList);
        } else {
            alert(result.result?.error || 'Failed to complete tour');
        }
    } catch (error) {
        console.error('Complete tour error:', error);
        alert('Failed to complete tour');
    } finally {
        if (confirmBtn) {
            confirmBtn.disabled = false;
            confirmBtn.innerHTML = '<i class="fa fa-check me-2"></i>Complete Tour';
        }
    }
}

function showPartialCompleteModal(btn) {
    partialCompleteTourLogId = parseInt(btn.dataset.tourLogId);

    // Clear previous reason
    document.getElementById('partialCompletionReason').value = '';

    showBsModal('partialCompleteModal');
}

async function confirmPartialComplete() {
    const reasonTextarea = document.getElementById('partialCompletionReason');
    const reason = reasonTextarea.value.trim();

    if (!reason) {
        alert('Please provide a reason for partial completion.');
        reasonTextarea.focus();
        return;
    }

    if (reason.length < 10) {
        alert('Please provide a more detailed reason (at least 10 characters).');
        reasonTextarea.focus();
        return;
    }

    const confirmBtn = document.getElementById('confirmPartialCompleteBtn');
    confirmBtn.disabled = true;
    confirmBtn.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i>Completing...';

    try {
        const response = await fetch('/guardpro/api/tour/complete', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    tour_log_id: partialCompleteTourLogId,
                    partial: true,
                    reason: reason
                }
            })
        });

        const result = await response.json();

        if (result.result && result.result.success) {
            hideBsModal('partialCompleteModal');
            if (pendingStartTourBtn) {
                const btn = pendingStartTourBtn;
                pendingStartTourBtn = null;
                partialCompleteTourLogId = null;
                blockedPatrolTourLogId = null;
                alert('Patrol closed. Starting your new tour...');
                await startTour(btn);
                return;
            }
            const logId = result.result.tour_log_id || partialCompleteTourLogId;
            window.location.href = '/guardpro/mobile/tours/summary/' + logId;
        } else {
            alert(result.result?.error || 'Failed to partially complete tour');
            confirmBtn.disabled = false;
            confirmBtn.innerHTML = '<i class="fa fa-check me-2"></i>Confirm Partial Completion';
        }
    } catch (error) {
        console.error('Partial complete tour error:', error);
        alert('Failed to partially complete tour');
        confirmBtn.disabled = false;
        confirmBtn.innerHTML = '<i class="fa fa-check me-2"></i>Confirm Partial Completion';
    }
}

div.script:
window.guardproVisitorIdPhoto = (function () {
    function showPreview(dataUrl, b64) {
        var hidden = document.getElementById('guardpro-id-photo-b64');
        if (hidden) {
            hidden.value = b64;
        }
        var img = document.getElementById('guardpro-id-photo-img');
        var preview = document.getElementById('guardpro-id-photo-preview');
        if (img) {
            img.src = dataUrl;
        }
        if (preview) {
            preview.style.display = '';
        }
    }
    function take() {
        var input = document.getElementById('guardpro-id-photo-input');
        if (input) {
            input.click();
        }
    }
    function onFileChange(input) {
        if (!input || !input.files || !input.files[0]) {
            return;
        }
        var file = input.files[0];
        var reader = new FileReader();
        reader.onload = function (e) {
            var dataUrl = e.target.result || '';
            var b64 = dataUrl.indexOf(',') >= 0 ? dataUrl.split(',')[1] : dataUrl;
            showPreview(dataUrl, b64);
        };
        reader.readAsDataURL(file);
    }
    function clear() {
        var hidden = document.getElementById('guardpro-id-photo-b64');
        var input = document.getElementById('guardpro-id-photo-input');
        var preview = document.getElementById('guardpro-id-photo-preview');
        var img = document.getElementById('guardpro-id-photo-img');
        if (hidden) {
            hidden.value = '';
        }
        if (input) {
            input.value = '';
        }
        if (img) {
            img.removeAttribute('src');
        }
        if (preview) {
            preview.style.display = 'none';
        }
    }
    document.addEventListener('DOMContentLoaded', function () {
        var input = document.getElementById('guardpro-id-photo-input');
        if (input) {
            input.addEventListener('change', function () {
                onFileChange(input);
            });
        }
        var hidden = document.getElementById('guardpro-id-photo-b64');
        if (hidden && hidden.value) {
            showPreview('data:image/jpeg;base64,' + hidden.value, hidden.value);
        }
        hidden && hidden.addEventListener('change', function () {
            if (hidden.value) {
                showPreview('data:image/jpeg;base64,' + hidden.value, hidden.value);
            }
        });
        // Returning visitor: autofill from prior visit when Emirates ID is entered
        var idInput = document.querySelector('form [name="id_number"]');
        var formRoot = idInput && idInput.closest('form');
        function fillIfEmpty(name, value) {
            if (!formRoot || !value) return;
            var el = formRoot.querySelector('[name="' + name + '"]');
            if (el && !(el.value || '').trim()) {
                el.value = value;
                el.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }
        function lookupReturningVisitor() {
            if (!idInput || !formRoot) return;
            var idNumber = (idInput.value || '').trim();
            if (idNumber.length < 5) return;
            fetch('/guardpro/api/visitor/lookup_by_id', {
                method: 'POST',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: { id_number: idNumber },
                    id: Date.now(),
                }),
            }).then(function (r) { return r.json(); }).then(function (data) {
                var result = data && data.result;
                if (!result || !result.success || !result.found || !result.fields) return;
                var f = result.fields;
                [
                    'name', 'mobile_number', 'email', 'company', 'nationality',
                    'occupation', 'employer_name', 'issuing_place',
                    'host_name', 'host_phone', 'host_email',
                    'host_community', 'host_unit_number',
                ].forEach(function (key) {
                    fillIfEmpty(key, f[key]);
                });
                if (f.gender) fillIfEmpty('gender', f.gender);
                if (f.date_of_birth) fillIfEmpty('date_of_birth', f.date_of_birth);
            }).catch(function () { /* ignore */ });
        }
        if (idInput) {
            idInput.addEventListener('change', lookupReturningVisitor);
            idInput.addEventListener('blur', lookupReturningVisitor);
        }
    });
    return { take: take, onFileChange: onFileChange, clear: clear, showPreview: showPreview };
})();

(function () {
    function mountOverlay(el) {
        if (!el) return null;
        var host = document.querySelector('.guardpro-mobile') || document.body;
        if (el.parentNode !== host) {
            host.appendChild(el);
        }
        return el;
    }
    function showStep(n) {
        [1, 2, 3].forEach(function (i) {
            var s = document.getElementById('gp-step-' + i);
            if (s) s.style.display = (i === n) ? '' : 'none';
            var d = document.getElementById('gp-dot-' + i);
            if (d) {
                d.classList.remove('active', 'done');
                if (i < n) d.classList.add('done');
                else if (i === n) d.classList.add('active');
            }
        });
    }
    function openWizard() {
        var el = document.getElementById('gp-incident-wizard');
        if (!el) {
            setTimeout(openWizard, 50);
            return;
        }
        mountOverlay(el);
        showStep(1);
        el.classList.add('gp-wizard-open');
        el.style.display = 'flex';
        document.body.style.overflow = 'hidden';
        document.querySelectorAll('.gp-type-row').forEach(function(t) { t.classList.remove('selected'); });
        var parentHidden = document.getElementById('gp-inc-form-parent');
        if (parentHidden) parentHidden.value = '';
        if (window.gpIncidentWizard && gpIncidentWizard.hideExcelForm) {
            gpIncidentWizard.hideExcelForm();
        }
        var search = document.getElementById('gp-parent-search');
        if (search) search.value = '';
        if (window.gpIncidentWizard && gpIncidentWizard.filterParents) {
            gpIncidentWizard.filterParents('');
        } else {
            document.querySelectorAll('#gp-parent-type-list .gp-type-row').forEach(function (row) {
                row.style.display = '';
            });
        }
        try { el.scrollTop = 0; } catch (e) {}
    }
    function closeWizard() {
        var el = document.getElementById('gp-incident-wizard');
        if (el) {
            el.classList.remove('gp-wizard-open');
            el.style.display = 'none';
        }
        document.body.style.overflow = '';
    }
    window.gpIncidentWizard = {
        open: openWizard,
        close: closeWizard,
        goStep: showStep,
        pickType: function () {},
        pickParent: function () {},
        pickParentFromBtn: function () {},
        hideExcelForm: function () {
            var host = document.getElementById('gp-excel-form-sections');
            if (host) host.innerHTML = '';
        },
        filterParents: function (query) {
            var q = String(query || '').toLowerCase().trim();
            var rows = document.querySelectorAll('#gp-parent-type-list .gp-type-row');
            var visible = 0;
            rows.forEach(function (row) {
                var hay = (row.getAttribute('data-search') || row.textContent || '').toLowerCase();
                var show = !q || hay.indexOf(q) !== -1;
                row.style.display = show ? '' : 'none';
                if (show) visible += 1;
            });
            var empty = document.getElementById('gp-parent-search-empty');
            if (empty) empty.style.display = visible ? 'none' : '';
        },
        openForType: function () { openWizard(); },
        validateStep2: function () {},
        submitForm: function () { return true; },
        showCategoryPanel: function () {},
        selectCategory: function () {},
        requestClose: function () {
            var step2 = document.getElementById('gp-step-2');
            var onForm = step2 && step2.style.display !== 'none';
            var step3 = document.getElementById('gp-step-3');
            if (step3 && step3.style.display !== 'none') onForm = true;
            if (onForm && !window.confirm('You have unsaved report details. Leave anyway and lose what you filled?')) return false;
            closeWizard();
            return true;
        },
        requestBack: function () {
            var step3 = document.getElementById('gp-step-3');
            if (step3 && step3.style.display !== 'none') {
                showStep(2);
                return true;
            }
            var step2 = document.getElementById('gp-step-2');
            if (step2 && step2.style.display !== 'none') {
                if (!window.confirm('You have unsaved report details. Leave anyway and lose what you filled?')) return false;
                showStep(1);
                return true;
            }
            return window.gpIncidentWizard.requestClose();
        },
        isDirty: function () { return false; },
        _mountOverlay: mountOverlay
    };
    var btn = document.getElementById('gp-btn-report-incident');
    if (btn) {
        btn.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            window.gpIncidentWizard.open();
        });
    }
})();

var gpIncidentWizard = (function() {
    var _type = '', _typeLabel = '';
    var _parentPickReady = false;
    var _historyPushed = false;
    var _suppressPopstate = false;
    // True while intentionally navigating away (submit / successful close)
