            property_damage: [
                ['gp-field-damage-type', 'Please describe the type and extent of damage.']
            ],
            community_violation: [
                ['gp-field-cv-details', 'Please describe the community violation.']
            ],
            parking_violation: [
                ['gp-field-park-details', 'Please describe the parking violation.']
            ],
            equipment_malfunction: [
                ['gp-field-equipment-issue', 'Please describe the equipment issue.']
            ]
        };
        var checks = typeRequired[type] || [];
        for (var i = 0; i < checks.length; i++) {
