            if (!requireVisibleField(document.querySelector('#mobile-statement-fields [name="statement_text"]'), 'Please enter the statement content.')) return false;
        }
        var found = document.getElementById('mobile-found-fields');
        if (found && found.style.display !== 'none') {
            if (!requireVisibleField(document.querySelector('#mobile-found-fields [name="found_person_name"]'), 'Please enter who found the item.')) return false;
            if (!requireVisibleField(document.querySelector('#mobile-found-fields [name="found_item_description"]'), 'Please describe the found item.')) return false;
        }
        var ret = document.getElementById('mobile-return-fields');
        if (ret && ret.style.display !== 'none') {
