        (parent.sections || []).forEach(function (sec) {
            html += '<div class="card mb-3 border-primary">' +
                '<div class="card-header text-white py-2" style="background:#1B365D;"><strong>' +
                escHtml(sec.name) + '</strong></div><div class="card-body">';
            (sec.fields || []).forEach(function (fld) {
                var req = fld.required ? ' <span class="text-danger">*</span>' : '';
                var nameAttr = 'form_field_' + fld.id;
                var hint = fld.hint || '';
                html += '<div class="mb-3"><label class="form-label fw-semibold">' +
