                if (fld.field_type === 'text') {
                    html += '<textarea class="form-control" name="' + nameAttr + '" rows="4"' +
                        (hint ? ' placeholder="' + escHtml(hint) + '"' : '') + '></textarea>';
                    if (hint) html += '<small class="text-muted d-block mt-1">' + escHtml(hint) + '</small>';
                } else if (fld.field_type === 'boolean') {
                    html += '<select class="form-select" name="' + nameAttr + '">' +
                        '<option value="">Select…</option>' +
                        '<option value="Yes">Yes</option>' +
                        '<option value="No">No</option></select>';
                } else if (fld.field_type === 'selection') {
                    html += '<select class="form-select" name="' + nameAttr + '"><option value="">Select…</option>';
                    (fld.options || []).forEach(function (opt) {
                        html += '<option value="' + escHtml(opt) + '">' + escHtml(opt) + '</option>';
                    });
                    html += '</select>';
                } else if (fld.field_type === 'date') {
                    html += '<input type="date" class="form-control" name="' + nameAttr + '"/>';
                } else if (fld.field_type === 'time') {
                    html += '<input type="time" class="form-control" name="' + nameAttr + '"/>';
                } else if (fld.field_type === 'integer') {
                    html += '<input type="number" class="form-control" name="' + nameAttr + '"/>';
                } else if (fld.field_type === 'signature') {
                    html += '<canvas id="gp-excel-sig-' + fld.id + '" class="gp-excel-sig-canvas"' +
                        ' style="width:100%;height:140px;border:1px solid #ccc;border-radius:4px;background:#fff;touch-action:none;"></canvas>' +
                        '<input type="hidden" name="' + nameAttr + '" id="gp-excel-sig-input-' + fld.id + '"/>' +
                        '<button type="button" class="btn btn-sm btn-outline-secondary mt-1" ' +
                        'onclick="clearSignatureCanvas(&quot;gp-excel-sig-' + fld.id +
                        '&quot;,&quot;gp-excel-sig-input-' + fld.id + '&quot;)">Clear</button>';
                } else if (fld.field_type === 'media') {
