        }
        host.innerHTML = '<div class="text-muted small mb-3"><i class="fa fa-spinner fa-spin me-1"></i>Loading form fields…</div>';
        fetch('/guardpro/mobile/incident/form-parent/' + encodeURIComponent(parentId), {
            credentials: 'same-origin',
            headers: { 'Accept': 'application/json' },
        }).then(function (r) { return r.json(); }).then(function (data) {
            if (!data || !data.ok || !data.parent) {
