    function pickParent(id, label, code, categoryId) {
        _type = code || ''; _typeLabel = label || '';
        document.querySelectorAll('.gp-type-row').forEach(function(t) { t.classList.remove('selected'); });
        var parentHidden = document.getElementById('gp-inc-form-parent');
        if (parentHidden) parentHidden.value = String(id || '');
        var catInput = document.getElementById('gp-inc-category');
        if (catInput && categoryId) catInput.value = String(categoryId);
        var wizardTypeHidden = document.getElementById('gp-inc-wizard-type');
        if (wizardTypeHidden) wizardTypeHidden.value = code || '';
        window._gpWizardType = code || '';
        var titleEl = document.getElementById('gp-inc-title');
        var descEl = document.getElementById('gp-inc-desc');
        if (titleEl) titleEl.value = label || code || 'Incident Report';
        if (descEl && !descEl.value) descEl.value = label || 'Incident report';
        renderExcelForm(id);
        // Hide legacy type-specific blocks for Excel parents
        if (window.GPIncidentMobile && GPIncidentMobile.toggleWizardTypeFields) {
            GPIncidentMobile.toggleWizardTypeFields('');
        }
        if (typeof toggleMobileIncidentCategoryFields === 'function') {
            toggleMobileIncidentCategoryFields('', '');
        }
        goStep(2);
        var badge = document.getElementById('gp-type-badge');
        if (badge) badge.innerHTML = '<i class="fa fa-file-text-o me-1" style="color:#1B365D"></i>' + (label || '');
        var heading = document.getElementById('gp-wizard-heading');
        if (heading) heading.textContent = label || 'Report Incident';
    }
    function pickType(type, label, icon, color) {
        _type = type; _typeLabel = label;
        document.querySelectorAll('.gp-type-row').forEach(function(t) { t.classList.remove('selected'); });
        try {
            if (typeof event !== 'undefined' && event && event.currentTarget) {
                event.currentTarget.classList.add('selected');
            }
        } catch (e) {}
        document.getElementById('gp-inc-category').value = '';
        var parentHidden = document.getElementById('gp-inc-form-parent');
        if (parentHidden) parentHidden.value = '';
        hideExcelForm();
        var wizardTypeHidden = document.getElementById('gp-inc-wizard-type');
        if (wizardTypeHidden) wizardTypeHidden.value = type;
        window._gpWizardType = type;
        try { sessionStorage.setItem('gp_inc_wizard_type', type); } catch (e) {}
        if (typeof applyIncidentTemplate === 'function') applyIncidentTemplate(type);
        showCategoryPanel(type);
        if (window.GPIncidentMobile && GPIncidentMobile.toggleWizardTypeFields) {
            GPIncidentMobile.toggleWizardTypeFields(type);
        }
        goStep(2);
        var badge = document.getElementById('gp-type-badge');
        if (badge) badge.innerHTML = '<i class="fa ' + icon + ' me-1" style="color:' + color + '"/>' + label;
        var heading = document.getElementById('gp-wizard-heading');
        if (heading && type === 'community_violation') {
            heading.textContent = 'Community Violation';
        } else if (heading) {
            heading.textContent = 'Report Incident';
        }
    }
    function openForType(type) {
        var codeMap = {
            community_violation: 'COMM_VIO',
            parking_violation: 'PARK_VIO',
            property_damage: 'PROP_DMG',
            other: 'STATEMENT'
        };
        var want = codeMap[type] || type;
        open();
        if (!want || want === 'false' || want === 'None' || want === 'null') {
            return;
        }
        var parents = loadFormParents();
        for (var i = 0; i < parents.length; i++) {
            if (parents[i].code === want || parents[i].code === type) {
                // Deep-link open is intentional — allow pick immediately
                _parentPickReady = true;
                pickParent(parents[i].id, parents[i].name, parents[i].code, parents[i].category_id || '');
                return;
            }
        }
        var meta = {
            suspicious_person: ['Suspicious Person', 'fa-user-secret', '#3949ab'],
            medical_emergency: ['Medical Emergency', 'fa-ambulance', '#c62828'],
            property_damage: ['Property Damage', 'fa-exclamation-triangle', '#e65100'],
            community_violation: ['Community Violation', 'fa-home', '#6a1b9a'],
            parking_violation: ['Parking Violation', 'fa-car', '#1565c0'],
            security_breach: ['Security Breach', 'fa-shield', '#880e4f'],
            equipment_malfunction: ['Equipment Issue', 'fa-cog', '#4e342e'],
            other: ['Other', 'fa-file-text', '#546e7a']
        };
        var m = meta[type];
        if (m) {
            _parentPickReady = true;
            pickType(type, m[0], m[1], m[2]);
        }
    }
    function validateStep2() {
        var t = document.getElementById('gp-inc-title');
        var d = document.getElementById('gp-inc-desc');
        var cat = document.getElementById('gp-inc-category');
        var parentHidden = document.getElementById('gp-inc-form-parent');
        // Auto-fill title/description from selected category (fields removed from UI)
        var fallback = _typeLabel || window._gpWizardType || 'Incident Report';
        if (t && !t.value.trim()) t.value = fallback;
        if (d && !d.value.trim()) d.value = fallback;
        if ((!cat || !cat.value) && parentHidden && parentHidden.value) {
            // Parent category supplies linked category_id
        } else if (!cat || !cat.value) {
            alert('Please select a parent category for this report.');
            goStep(1);
            return;
        }
        if (!validateTypeAndCategoryFields()) {
            return;
        }
        var wizardTypeHidden = document.getElementById('gp-inc-wizard-type');
        if (wizardTypeHidden) wizardTypeHidden.value = _type || window._gpWizardType || wizardTypeHidden.value || '';

        var form = document.getElementById('incidentReportForm');
        if (form) {
            form.querySelectorAll('input[data-relay]').forEach(function(h) { h.remove(); });
            var sectionIds = ['mobile-statement-fields', 'mobile-found-fields', 'mobile-return-fields'];
            sectionIds.forEach(function(sid) {
                var section = document.getElementById(sid);
                if (!section || section.style.display === 'none') return;
                section.querySelectorAll('[name]').forEach(function(field) {
                    if (field.tagName === 'CANVAS') return;
                    var val = (field.type === 'checkbox') ? (field.checked ? 'on' : '') : (field.value || '');
                    if (!val) return;
                    var h = document.createElement('input');
                    h.type = 'hidden';
                    h.name = field.name;
                    h.value = val;
                    h.dataset.relay = sid;
                    form.appendChild(h);
                });
            });
            if (window.GPIncidentMobile && GPIncidentMobile.relayWizardTypeFields) {
                GPIncidentMobile.relayWizardTypeFields(form);
            }
        }

        var sev = document.getElementById('gp-inc-severity').value;
        var sevLabel = {'low':'Low','medium':'Medium','high':'High','critical':'Critical'}[sev] || sev;
        var summary = document.getElementById('gp-step3-summary');
        if (summary) summary.innerHTML =
            '<strong>' + (t && t.value ? t.value : fallback) + '</strong>' +
            '<br><span class="text-muted">' + sevLabel + ' severity</span>' +
            (_typeLabel ? ' &middot; ' + _typeLabel : '');
        goStep(3);
    }
    function syncWizardFormFields() {
        var titleEl = document.getElementById('gp-inc-title');
        var cat = document.getElementById('gp-inc-category');
        var wizardType = _type || window._gpWizardType || '';
        if (!wizardType) {
            try { wizardType = sessionStorage.getItem('gp_inc_wizard_type') || ''; } catch (e) {}
        }
        if (!wizardType && titleEl && window.GPIncidentMobile && GPIncidentMobile.inferWizardTypeFromTitle) {
            wizardType = GPIncidentMobile.inferWizardTypeFromTitle(titleEl.value);
        }
        if ((!cat || !cat.value) && wizardType) {
            showCategoryPanel(wizardType);
            cat = document.getElementById('gp-inc-category');
        }
        var wizardTypeHidden = document.getElementById('gp-inc-wizard-type');
        if (wizardTypeHidden) wizardTypeHidden.value = wizardType || wizardTypeHidden.value || '';
        var form = document.getElementById('incidentReportForm');
        if (form && window.GPIncidentMobile && GPIncidentMobile.relayWizardTypeFields) {
            GPIncidentMobile.relayWizardTypeFields(form);
        }
    }
    function submitForm(form, event) {
        syncWizardFormFields();
        var cat = document.getElementById('gp-inc-category');
        if (!cat || !cat.value) {
            alert('Incident category is missing. Please go back and choose the incident type again.');
            goStep(2);
            return false;
        }
        // Form is being saved — do not ask "leave and lose data?"
        markAllowLeave();
        return typeof getLocationAndSubmit !== 'undefined'
            ? getLocationAndSubmit(form, event)
            : true;
    }
    var api = { open: open, close: close, goStep: goStep, pickType: pickType, pickParent: pickParent, pickParentFromBtn: pickParentFromBtn, filterParents: filterParents, hideExcelForm: hideExcelForm, openForType: openForType, validateStep2: validateStep2, submitForm: submitForm, showCategoryPanel: showCategoryPanel, selectCategory: selectCategory, requestClose: requestClose, requestBack: requestBack, isDirty: isDirty };
    window.gpIncidentWizard = api;
    window.addEventListener('popstate', function () {
        if (_suppressPopstate) return;
        if (!isWizardOpen()) return;
        if (isDirty() && !confirmDiscard()) {
            try {
                history.pushState({ gpIncidentWizard: 1 }, '');
                _historyPushed = true;
            } catch (err) {}
            return;
        }
        _historyPushed = false;
        var el = document.getElementById('gp-incident-wizard');
        if (el) {
            el.classList.remove('gp-wizard-open');
            el.style.display = 'none';
        }
        document.body.style.overflow = '';
    });
    window.addEventListener('beforeunload', function (e) {
        if (isDirty()) {
            e.preventDefault();
            e.returnValue = '';
        }
    });
    return api;
})();
// Close wizard on backdrop click (confirm if form has data)
document.addEventListener('click', function(e) {
    var overlay = document.getElementById('gp-incident-wizard');
    if (overlay && e.target === overlay) gpIncidentWizard.requestClose();
});
// Auto-open wizard for deep links (?open_wizard=community_violation)
document.addEventListener('DOMContentLoaded', function() {
    var openType = '';
    try {
        var overlay = document.getElementById('gp-incident-wizard');
        openType = (overlay && overlay.getAttribute('data-open-wizard')) || '';
    } catch (e) {}
    if (!openType) {
        try {
            var params = new URLSearchParams(window.location.search || '');
            openType = params.get('open_wizard') || '';
        } catch (e) {}
    }
    if (openType === 'false' || openType === 'None' || openType === 'null') {
        openType = '';
    }
    if (openType && window.gpIncidentWizard && gpIncidentWizard.openForType) {
        setTimeout(function() { gpIncidentWizard.openForType(openType); }, 80);
    }
});

t.script:
// getLocationAndSubmit is provided by mobile_navigation.js (file-safe submit).
// Do not redefine it here — form.submit() drops multipart file uploads on mobile WebView.

function previewIncidentImages(input) {
    const previewContainer = document.getElementById('image-preview-container');
    if (!previewContainer) {
        return;
    }
    previewContainer.innerHTML = '';

    if (!input.files || !input.files.length) {
        return;
    }

    Array.from(input.files).forEach(function(file) {
        const name = (file.name || '').toLowerCase();
        const isHeic = name.endsWith('.heic') || name.endsWith('.heif');
        const isImage = (file.type && file.type.indexOf('image/') === 0) || isHeic;
        if (!isImage) {
            return;
        }
        if (isHeic && (!file.type || file.type.indexOf('image/') !== 0)) {
            const note = document.createElement('div');
            note.className = 'small text-warning w-100';
            note.textContent = file.name + ' (HEIC) — preview may not show; photo will still upload.';
            previewContainer.appendChild(note);
        }
        const reader = new FileReader();
        reader.onload = function(e) {
            const imgWrapper = document.createElement('div');
            imgWrapper.style.cssText = 'position: relative; width: 80px; height: 80px;';

            const img = document.createElement('img');
            img.src = e.target.result;
            img.style.cssText = 'width: 100%; height: 100%; object-fit: cover; border-radius: 5px; border: 2px solid #ddd;';

            imgWrapper.appendChild(img);
            previewContainer.appendChild(imgWrapper);
        };
        reader.readAsDataURL(file);
    });
}

function applyIncidentTemplate(templateType) {
    var templates = {
        'suspicious_person': {
            title: 'Suspicious Person Observed',
            description: 'Observed a suspicious individual on the premises.\n\nDetails:\n- Location: [Specify exact location]\n- Time: [Current time]\n- Description: [Physical description - height, clothing, behavior]\n- Actions taken: [What you did - asked to leave, called supervisor, etc.]\n- Current status: [Still on premises / Left the area]',
            severity: 'medium'
        },
        'property_damage': {
            title: 'Property Damage Discovered',
            description: 'Property damage has been discovered on the premises.\n\nDetails:\n- Location: [Exact location of damage]\n- Type of damage: [Broken window, graffiti, vandalism, etc.]\n- Extent: [Minor / Moderate / Severe]\n- Estimated time occurred: [If known]\n- Photos: [Attach photos below]\n- Area secured: [Yes / No]',
            severity: 'high'
        },
        'medical_emergency': {
            title: 'Medical Emergency',
            description: 'Medical emergency requiring immediate attention.\n\nDetails:\n- Patient: [Name if known / Unknown person]\n- Location: [Exact location]\n- Condition: [Conscious / Unconscious / Injured]\n- Symptoms: [Describe symptoms]\n- Emergency services called: [Yes - Time: __ / No]\n- First aid provided: [Describe any first aid given]\n- Current status: [Being treated / Transported / etc.]',
            severity: 'critical'
        },
        'equipment_malfunction': {
            title: 'Equipment Malfunction',
            description: 'Equipment malfunction or failure detected.\n\nDetails:\n- Equipment: [Name/type of equipment]\n- Location: [Where equipment is located]\n- Issue: [Describe the malfunction]\n- Impact: [Critical / High / Medium / Low]\n- Safety hazard: [Yes / No]\n- Equipment tagged: [Yes / No]\n- Area cordoned off: [If applicable]',
            severity: 'medium'
        },
        'security_breach': {
            title: 'Security Breach',
            description: 'Security breach or unauthorized access detected.\n\nDetails:\n- Type: [Unauthorized entry / Intrusion / Access violation]\n- Location: [Exact location of breach]\n- Time discovered: [Current time]\n- Entry point: [Door / Window / Gate / etc.]\n- Items missing: [Yes - List items / No]\n- Intruder description: [If seen]\n- Police notified: [Yes - Time: __ / No]\n- Area secured: [Yes / No]',
            severity: 'critical'
        }
    };

    var template = templates[templateType];
    if (template) {
        // FIX: use wizard-specific field IDs (not the detail-page IDs)
        var titleEl = document.getElementById('gp-inc-title');
        var descEl  = document.getElementById('gp-inc-desc');
        var sevEl   = document.getElementById('gp-inc-severity');
        if (titleEl) titleEl.value = template.title;
        if (descEl)  descEl.value = template.description;
        if (sevEl)   sevEl.value = template.severity;
    }
}

function setupSignatureCanvas(canvasId, inputId) {
    const canvas = document.getElementById(canvasId);
    const input = document.getElementById(inputId);
    if (!canvas || !input) return;
    const ctx = canvas.getContext('2d');
    const ratio = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const width = Math.max(280, Math.floor(rect.width || canvas.clientWidth || 280));
    const height = Math.max(140, Math.floor(rect.height || canvas.clientHeight || 140));
    canvas.width = Math.floor(width * ratio);
    canvas.height = Math.floor(height * ratio);
    ctx.scale(ratio, ratio);
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    let drawing = false;
    const point = (e) => {
        const r = canvas.getBoundingClientRect();
        const src = e.touches ? e.touches[0] : e;
        return { x: src.clientX - r.left, y: src.clientY - r.top };
    };
    const start = (e) => { drawing = true; const p = point(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); if (e.cancelable) e.preventDefault(); };
    const move = (e) => { if (!drawing) return; const p = point(e); ctx.lineTo(p.x, p.y); ctx.stroke(); input.value = canvas.toDataURL('image/png'); if (e.cancelable) e.preventDefault(); };
    const end = () => { drawing = false; };
    canvas.addEventListener('mousedown', start);
    canvas.addEventListener('mousemove', move);
    canvas.addEventListener('mouseup', end);
    canvas.addEventListener('mouseleave', end);
    canvas.addEventListener('touchstart', start, { passive: false });
    canvas.addEventListener('touchmove', move, { passive: false });
    canvas.addEventListener('touchend', end);
}

function clearSignatureCanvas(canvasId, inputId) {
    const canvas = document.getElementById(canvasId);
    const input = document.getElementById(inputId);
    if (!canvas || !input) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    input.value = '';
}

// Toggle Statement / Found / Return blocks from category name or code
function toggleMobileIncidentCategoryFields(categoryName, categoryCode) {
    var name = (categoryName || '').toLowerCase();
    var code = (categoryCode || '').toUpperCase();
    var statement = document.getElementById('mobile-statement-fields');
    var found     = document.getElementById('mobile-found-fields');
    var ret       = document.getElementById('mobile-return-fields');
    if (!statement || !found || !ret) return;
    var isStatement = (window.GPIncidentMobile && GPIncidentMobile.isStatementCategory)
        ? GPIncidentMobile.isStatementCategory(code, name)
        : (code === 'STMT' || code === 'STATEMENT' || name.indexOf('statement') !== -1);
    var isFound = (window.GPIncidentMobile && GPIncidentMobile.isFoundCategory)
        ? GPIncidentMobile.isFoundCategory(code, name)
        : (code === 'FOUND' || code === 'FOUND ITEM' || name.indexOf('found item') !== -1);
    var isReturn = (window.GPIncidentMobile && GPIncidentMobile.isReturnCategory)
        ? GPIncidentMobile.isReturnCategory(code, name)
        : (code === 'RETURN' || code === 'RETURN FORM' || name.indexOf('return form') !== -1);
    statement.style.display = isStatement ? 'block' : 'none';
    found.style.display     = isFound ? 'block' : 'none';
    ret.style.display       = isReturn ? 'block' : 'none';
    setTimeout(function() {
        setupSignatureCanvas('statement-person-signature-canvas', 'statement-person-signature-input');
        setupSignatureCanvas('security-officer-signature-canvas-create', 'security-officer-signature-input-create');
        setupSignatureCanvas('found-person-signature-canvas', 'found-person-signature-input');
        setupSignatureCanvas('return-recipient-signature-canvas', 'return-recipient-signature-input');
    }, 0);
}

document.addEventListener('DOMContentLoaded', function() {
    setupSignatureCanvas('statement-person-signature-canvas', 'statement-person-signature-input');
    setupSignatureCanvas('security-officer-signature-canvas-create', 'security-officer-signature-input-create');
    setupSignatureCanvas('found-person-signature-canvas', 'found-person-signature-input');
    setupSignatureCanvas('return-recipient-signature-canvas', 'return-recipient-signature-input');
});

// Show/hide conditional fields
function toggleConditionalFields() {
    // Police report number
    const policeNotified = document.getElementById('police_notified');
    const policeReportGroup = document.getElementById('police_report_group');
    if (policeNotified) {
        policeNotified.addEventListener('change', function() {
            policeReportGroup.style.display = this.checked ? 'block' : 'none';
        });
        policeReportGroup.style.display = policeNotified.checked ? 'block' : 'none';
    }

    // Injury details
    const injuries = document.getElementById('injuries');
    const injuryDetailsGroup = document.getElementById('injury_details_group');
    if (injuries) {
        injuries.addEventListener('change', function() {
            injuryDetailsGroup.style.display = this.checked ? 'block' : 'none';
        });
        injuryDetailsGroup.style.display = injuries.checked ? 'block' : 'none';
    }

    // Damage details
    const propertyDamage = document.getElementById('property_damage');
    const damageDetailsGroup = document.getElementById('damage_details_group');
    const estimatedCostGroup = document.getElementById('estimated_cost_group');
    if (propertyDamage) {
        propertyDamage.addEventListener('change', function() {
            const show = this.checked;
            damageDetailsGroup.style.display = show ? 'block' : 'none';
            estimatedCostGroup.style.display = show ? 'block' : 'none';
        });
        const show = propertyDamage.checked;
        damageDetailsGroup.style.display = show ? 'block' : 'none';
        estimatedCostGroup.style.display = show ? 'block' : 'none';
    }
}

function toggleMobileIncidentCategoryFieldsEdit() {
    const categorySelect = document.getElementById('category_id');
    const statement = document.getElementById('mobile-statement-fields-edit');
    const found = document.getElementById('mobile-found-fields-edit');
    const ret = document.getElementById('mobile-return-fields-edit');
    if (!categorySelect || !statement || !found || !ret) return;
    const selectedOpt = categorySelect.options[categorySelect.selectedIndex];
    const selectedText = selectedOpt ? selectedOpt.text.toLowerCase() : '';
    const selectedCode = selectedOpt ? (selectedOpt.getAttribute('data-code') || '') : '';
    const isStatement = (window.GPIncidentMobile && GPIncidentMobile.isStatementCategory)
        ? GPIncidentMobile.isStatementCategory(selectedCode, selectedText)
        : (selectedCode === 'STMT' || selectedCode === 'STATEMENT' || selectedText.includes('statement'));
    const isFound = (window.GPIncidentMobile && GPIncidentMobile.isFoundCategory)
        ? GPIncidentMobile.isFoundCategory(selectedCode, selectedText)
        : (selectedCode === 'FOUND' || selectedCode === 'FOUND ITEM' || selectedText.includes('found item'));
    const isReturn = (window.GPIncidentMobile && GPIncidentMobile.isReturnCategory)
        ? GPIncidentMobile.isReturnCategory(selectedCode, selectedText)
        : (selectedCode === 'RETURN' || selectedCode === 'RETURN FORM' || selectedText.includes('return form'));
    statement.style.display = isStatement ? 'block' : 'none';
    found.style.display = isFound ? 'block' : 'none';
    ret.style.display = isReturn ? 'block' : 'none';
    if (window.GPIncidentMobile && GPIncidentMobile.toggleDetailSectionsByCategory) {
        GPIncidentMobile.toggleDetailSectionsByCategory(selectedCode);
    }
    if (window.GPIncidentMobile && GPIncidentMobile.filterDetailCategoryDropdown) {
        GPIncidentMobile.filterDetailCategoryDropdown(selectedCode);
    }
    setTimeout(function() {
        setupSignatureCanvas('statement-person-signature-canvas-edit', 'statement-person-signature-input-edit');
        setupSignatureCanvas('security-officer-signature-canvas-edit', 'security-officer-signature-input-edit');
        setupSignatureCanvas('found-person-signature-canvas-edit', 'found-person-signature-input-edit');
        setupSignatureCanvas('return-recipient-signature-canvas-edit', 'return-recipient-signature-input-edit');
    }, 0);
}

function setupSignatureCanvas(canvasId, inputId) {
    const canvas = document.getElementById(canvasId);
    const input = document.getElementById(inputId);
    if (!canvas || !input) return;
    const ctx = canvas.getContext('2d');
    const ratio = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const width = Math.max(280, Math.floor(rect.width || canvas.clientWidth || 280));
    const height = Math.max(140, Math.floor(rect.height || canvas.clientHeight || 140));
    canvas.width = Math.floor(width * ratio);
    canvas.height = Math.floor(height * ratio);
    ctx.scale(ratio, ratio);
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    let drawing = false;
    const point = (e) => {
        const r = canvas.getBoundingClientRect();
        const src = e.touches ? e.touches[0] : e;
        return { x: src.clientX - r.left, y: src.clientY - r.top };
    };
    const start = (e) => { drawing = true; const p = point(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); if (e.cancelable) e.preventDefault(); };
    const move = (e) => { if (!drawing) return; const p = point(e); ctx.lineTo(p.x, p.y); ctx.stroke(); input.value = canvas.toDataURL('image/png'); if (e.cancelable) e.preventDefault(); };
    const end = () => { drawing = false; };
    canvas.addEventListener('mousedown', start);
    canvas.addEventListener('mousemove', move);
    canvas.addEventListener('mouseup', end);
    canvas.addEventListener('mouseleave', end);
    canvas.addEventListener('touchstart', start, { passive: false });
    canvas.addEventListener('touchmove', move, { passive: false });
    canvas.addEventListener('touchend', end);
}

function clearSignatureCanvas(canvasId, inputId) {
    const canvas = document.getElementById(canvasId);
    const input = document.getElementById(inputId);
    if (!canvas || !input) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    input.value = '';
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', function() {
    toggleConditionalFields();
    toggleMobileIncidentCategoryFieldsEdit();
    const categorySelect = document.getElementById('category_id');
    if (categorySelect) {
        categorySelect.addEventListener('change', toggleMobileIncidentCategoryFieldsEdit);
    }
    setupSignatureCanvas('statement-person-signature-canvas-edit', 'statement-person-signature-input-edit');
    setupSignatureCanvas('security-officer-signature-canvas-edit', 'security-officer-signature-input-edit');
    setupSignatureCanvas('found-person-signature-canvas-edit', 'found-person-signature-input-edit');
    setupSignatureCanvas('return-recipient-signature-canvas-edit', 'return-recipient-signature-input-edit');
});

// Image preview function
function previewIncidentImages(input) {
    const previewContainer = document.getElementById('image-preview-container');
    if (!previewContainer) return;

    previewContainer.innerHTML = '';

    if (input.files) {
        Array.from(input.files).forEach((file, index) => {
            if (file.type.startsWith('image/')) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    const imgWrapper = document.createElement('div');
                    imgWrapper.style.cssText = 'position: relative; width: 80px; height: 80px;';

                    const img = document.createElement('img');
                    img.src = e.target.result;
                    img.style.cssText = 'width: 100%; height: 100%; object-fit: cover; border-radius: 5px; border: 2px solid #ddd;';

                    imgWrapper.appendChild(img);
                    previewContainer.appendChild(imgWrapper);
                };
                reader.readAsDataURL(file);
            }
        });
    }
}

// Location capture function
function getLocationAndSubmit(form, event) {
    if (event) {
        event.preventDefault();
    }

    const latField = form.querySelector('[name="latitude"]');
    const lngField = form.querySelector('[name="longitude"]');
    const submitBtn = form.querySelector('button[type="submit"]');
    const originalText = submitBtn ? submitBtn.innerHTML : '';

    // Disable submit button to prevent double submission
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Saving...';
    }

    // Create a function to submit the form properly
    const submitForm = function() {
        try {
            // Remove the onsubmit handler temporarily to avoid infinite loop
            const originalOnSubmit = form.onsubmit;
            form.onsubmit = null;

            // Use requestSubmit if available (properly triggers validation and submission)
            if (typeof form.requestSubmit === 'function') {
                form.requestSubmit();
            } else {
                // Fallback: create a temporary submit button and click it
                // This ensures all form data including files are included
                const tempSubmit = document.createElement('button');
                tempSubmit.type = 'submit';
                tempSubmit.style.display = 'none';
                form.appendChild(tempSubmit);
                tempSubmit.click();
                setTimeout(function() {
                    if (form.contains(tempSubmit)) {
                        form.removeChild(tempSubmit);
                    }
                }, 100);
            }

            // Restore onsubmit handler after a delay
            setTimeout(function() {
                form.onsubmit = originalOnSubmit;
            }, 1000);
        } catch (error) {
            console.error('[GuardLink Mobile] Error submitting form:', error);
            // Last resort: direct submit
            form.submit();
        }
    };

    // Check if geolocation is available
    if (navigator.geolocation) {
        // Set a timeout to ensure form submits even if geolocation fails
        const locationTimeout = setTimeout(function() {
            console.warn('[GuardLink Mobile] Location timeout, submitting without location');
            submitForm();
        }, 6000); // 6 second timeout

        navigator.geolocation.getCurrentPosition(
            function(position) {
                clearTimeout(locationTimeout);
                if (latField) latField.value = position.coords.latitude;
                if (lngField) lngField.value = position.coords.longitude;
                console.log('[GuardLink Mobile] Location captured:', position.coords.latitude, position.coords.longitude);
                submitForm();
            },
            function(error) {
                clearTimeout(locationTimeout);
                console.warn('[GuardLink Mobile] Location error:', error.message || error);
                console.warn('[GuardLink Mobile] Submitting form without location');
                submitForm();
            },
            { 
                timeout: 5000, 
                enableHighAccuracy: true,
                maximumAge: 30000 // Accept cached position up to 30 seconds old
            }
        );
    } else {
        // Geolocation not available, submit immediately
        console.warn('[GuardLink Mobile] Geolocation not available, submitting without location');
        submitForm();
    }

    return false;
}

// Fallback function if main JS doesn't load
if (typeof getLocationAndSubmit === 'undefined') {
    console.warn('[GuardLink Mobile] Main JS not loaded, using inline fallback');
    window.getLocationAndSubmit = function(form, event) {
        console.log('[Guard Pro Mobile Inline] getLocationAndSubmit called');

        if (event) {
            event.preventDefault();
        }

        var latField = form.querySelector('[name="latitude"]');
        var lngField = form.querySelector('[name="longitude"]');
        var submitBtn = form.querySelector('button[type="submit"]');
        var originalText = submitBtn ? submitBtn.innerHTML : '';

        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = ' Getting location...';
        }

        if (navigator.geolocation) {
            var timeout = setTimeout(function() {
                console.warn('[Guard Pro Mobile Inline] Location timeout');
                form.submit();
            }, 6000);

            navigator.geolocation.getCurrentPosition(
                function(position) {
                    clearTimeout(timeout);
                    if (latField) latField.value = position.coords.latitude;
                    if (lngField) lngField.value = position.coords.longitude;
                    console.log('[Guard Pro Mobile Inline] Location captured:', position.coords.latitude, position.coords.longitude);
                    form.submit();
                },
                function(error) {
                    clearTimeout(timeout);
                    console.warn('[Guard Pro Mobile Inline] Location error:', error.message);
                    form.submit();
                },
                { timeout: 5000, enableHighAccuracy: true, maximumAge: 30000 }
            );
        } else {
            console.warn('[Guard Pro Mobile Inline] Geolocation not available');
            form.submit();
        }

        return false;
    };
} else {
    console.log('[GuardLink Mobile] Main JS loaded successfully');
}

(function () {
    function normalize(value) {
        return (value || '').toString().toLowerCase();
    }

    function initCourseSearch() {
        const searchInput = document.getElementById('course-search-input');
        const clearBtn = document.getElementById('course-search-clear');
        const noResults = document.getElementById('course-search-no-results');
        const countLabel = document.getElementById('course-search-count');
        const cards = Array.from(document.querySelectorAll('.course-card'));

        if (!searchInput || !clearBtn || cards.length === 0) {
            return;
        }

        const total = cards.length;
        function updateCount(visible) {
            if (countLabel) {
                countLabel.textContent = `${visible}/${total} courses`;
            }
        }

        function applySearch() {
            const query = normalize(searchInput.value.trim());
            let visibleCount = 0;

            cards.forEach((card) => {
                const haystack = [
                    card.getAttribute('data-course-name'),
                    card.getAttribute('data-course-category'),
                    card.getAttribute('data-course-description'),
                ].map(normalize).join(' ');

                const matched = !query || haystack.includes(query);
                card.classList.toggle('d-none', !matched);
                if (matched) {
                    visibleCount += 1;
                }
            });

            if (noResults) {
                noResults.classList.toggle('d-none', visibleCount !== 0);
            }
            updateCount(visibleCount);
        }

        searchInput.addEventListener('input', applySearch);
        clearBtn.addEventListener('click', function () {
            searchInput.value = '';
            applySearch();
            searchInput.focus();
        });
        applySearch();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCourseSearch);
    } else {
        initCourseSearch();
    }
})();

// Offline Training Management
class OfflineTrainingManager {
    constructor() {
        this.cacheName = 'guardpro-training-cache-v1';
        this.dbName = 'guardpro-training-offline';
        this.isOnline = navigator.onLine;
        this.initOfflineSupport();
    }

    async initOfflineSupport() {
        // Register service worker for caching
        if ('serviceWorker' in navigator) {
            try {
                await navigator.serviceWorker.register('/guardpro/static/src/js/training-sw.js');
            } catch (error) {
                console.log('Service worker registration failed:', error);
            }
        }

        // Listen for online/offline events
        window.addEventListener('online', () => this.handleOnline());
        window.addEventListener('offline', () => this.handleOffline());

        // Initialize IndexedDB for offline data storage
        this.initDB();
    }

    async initDB() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(this.dbName, 1);

            request.onerror = () => reject(request.error);
            request.onsuccess = () => {
                this.db = request.result;
                resolve();
            };

            request.onupgradeneeded = (event) => {
                const db = event.target.result;
                if (!db.objectStoreNames.contains('slides')) {
                    db.createObjectStore('slides', { keyPath: 'id' });
                }
                if (!db.objectStoreNames.contains('progress')) {
                    db.createObjectStore('progress', { keyPath: 'slide_id' });
                }
            };
        });
    }

    async handleOnline() {
        this.isOnline = true;
        this.showOnlineIndicator();
        await this.syncOfflineData();
    }

    async handleOffline() {
        this.isOnline = false;
        this.showOfflineIndicator();
    }

    showOnlineIndicator() {
        this.updateConnectionStatus('Online - Data synced', 'success');
    }

    showOfflineIndicator() {
        this.updateConnectionStatus('Offline - Limited functionality available', 'warning');
    }

    updateConnectionStatus(message, type) {
        let indicator = document.getElementById('connection-status');
        if (!indicator) {
            indicator = document.createElement('div');
            indicator.id = 'connection-status';
            indicator.className = `alert alert-${type} alert-dismissible fade show position-fixed`;
            indicator.style.cssText = 'top: 70px; right: 10px; z-index: 9999; max-width: 300px;';
            indicator.innerHTML = `
                <small><i class="fa fa-wifi me-1"></i>${message}</small>
                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
            `;
            document.body.appendChild(indicator);
        } else {
            indicator.className = `alert alert-${type} alert-dismissible fade show position-fixed`;
            indicator.querySelector('small').innerHTML = `<i class="fa fa-wifi me-1"></i>${message}`;
        }

        // Auto-hide after 5 seconds
        setTimeout(() => {
            if (indicator) indicator.remove();
        }, 5000);
    }

    async cacheSlideForOffline(slideId, slideData) {
        if (!this.db) return;

        try {
            const transaction = this.db.transaction(['slides'], 'readwrite');
            const store = transaction.objectStore('slides');
            await store.put({
                id: slideId,
                data: slideData,
                cachedAt: Date.now()
            });
        } catch (error) {
            console.error('Failed to cache slide:', error);
        }
    }

    async getCachedSlide(slideId) {
        if (!this.db) return null;

        return new Promise((resolve) => {
            const transaction = this.db.transaction(['slides'], 'readonly');
            const store = transaction.objectStore('slides');
            const request = store.get(slideId);

            request.onsuccess = () => resolve(request.result?.data || null);
            request.onerror = () => resolve(null);
        });
    }

    async saveOfflineProgress(slideId, progress) {
        if (!this.db) return;

        try {
            const transaction = this.db.transaction(['progress'], 'readwrite');
            const store = transaction.objectStore('progress');
            await store.put({
                slide_id: slideId,
                progress: progress,
                savedAt: Date.now(),
                synced: false
            });
        } catch (error) {
            console.error('Failed to save offline progress:', error);
        }
    }

    async syncOfflineData() {
        if (!this.db || !this.isOnline) return;

        try {
            const transaction = this.db.transaction(['progress'], 'readonly');
            const store = transaction.objectStore('progress');
            const request = store.getAll();

            request.onsuccess = async () => {
                const unsyncedProgress = request.result.filter(p => !p.synced);

                for (const progress of unsyncedProgress) {
                    try {
                        // Sync progress with server
                        const response = await fetch(`/guardpro/api/training/slide/${progress.slide_id}/complete`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' }
                        });

                        if (response.ok) {
                            // Mark as synced
                            const syncTransaction = this.db.transaction(['progress'], 'readwrite');
                            const syncStore = syncTransaction.objectStore('progress');
                            await syncStore.put({ ...progress, synced: true });
                        }
                    } catch (error) {
                        console.error('Failed to sync progress:', error);
                    }
                }
            };
        } catch (error) {
            console.error('Failed to sync offline data:', error);
        }
    }
}

// Initialize offline training manager
const offlineManager = new OfflineTrainingManager();

// Handle course enrollment
document.addEventListener('DOMContentLoaded', function() {
    // Show connection status on load
    if (!navigator.onLine) {
        offlineManager.showOfflineIndicator();
    }

    document.querySelectorAll('.enroll-course-btn').forEach(btn => {
        btn.addEventListener('click', async function() {
            const courseId = this.getAttribute('data-course-id');
            const button = this;

            if (!navigator.onLine) {
                alert('Enrollment requires an internet connection. Please check your connection and try again.');
                return;
            }

            try {
                button.disabled = true;
                button.innerHTML = '<i class="fa fa-spinner fa-spin me-1"/>Enrolling...';

                const response = await fetch(`/guardpro/api/training/enroll/${courseId}`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    }
                });

                const data = await response.json();

                if (data.success) {
                    // Redirect to course page after successful enrollment
                    window.location.href = `/mobile/training/course/${courseId}`;
                } else {
                    alert(data.error || 'Failed to enroll in course');
                    button.disabled = false;
                    button.innerHTML = '<i class="fa fa-user-plus me-1"/>Enroll Now';
                }
            } catch (error) {
                alert('Network error. Please try again.');
                button.disabled = false;
                button.innerHTML = '<i class="fa fa-user-plus me-1"/>Enroll Now';
            }
        });
    });

    // Add offline download buttons to courses
    document.querySelectorAll('.card[data-course-id]').forEach(card => {
        const courseId = card.getAttribute('data-course-id');
        const cardBody = card.querySelector('.card-body');

        if (cardBody) {
            const downloadBtn = document.createElement('button');
            downloadBtn.className = 'btn btn-outline-secondary btn-sm mt-2';
            downloadBtn.innerHTML = '<i class="fa fa-download me-1"/>Download for Offline';
            downloadBtn.onclick = () => downloadCourseForOffline(courseId);
            cardBody.appendChild(downloadBtn);
        }
    });

    // Ensure course links work properly - verify and fix if needed
    function setupCourseLinks() {
        const courseLinks = document.querySelectorAll('a[href^="/mobile/training/course/"]');
        console.log('[Training] Found', courseLinks.length, 'course links');

        courseLinks.forEach((link, index) => {
            let href = link.getAttribute('href');
            console.log('[Training] Link', index + 1, '- href:', href, 'Element:', link);

            // Verify and fix href if needed
            if (!href || href === '#' || href === '') {
                // Try to get course ID from parent card
                const card = link.closest('.card[data-course-id]');
                if (card) {
                    const courseId = card.getAttribute('data-course-id');
                    if (courseId) {
                        href = '/mobile/training/course/' + courseId;
                        link.setAttribute('href', href);
                        console.log('[Training] Fixed href to:', href);
                    } else {
                        console.error('[Training] Card found but no course-id attribute');
                    }
                } else {
                    console.error('[Training] No parent card with data-course-id found');
                }
            }

            // Ensure link is clickable
            link.style.pointerEvents = 'auto';
            link.style.cursor = 'pointer';
            link.style.textDecoration = 'none';

            // Remove any existing click handlers to avoid conflicts
            const newLink = link.cloneNode(true);
            link.parentNode.replaceChild(newLink, link);

            // Add explicit click handler that forces navigation
            newLink.addEventListener('click', function(e) {
                const targetHref = this.getAttribute('href');
                console.log('[Training] Link clicked! Navigating to:', targetHref);

                if (targetHref && targetHref !== '#' && targetHref !== '' && targetHref.startsWith('/mobile/training/course/')) {
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    // Force navigation immediately
                    window.location.href = targetHref;
                    return false;
                } else {
                    console.error('[Training] Invalid href:', targetHref);
                    e.preventDefault();
                    return false;
                }
            }, { passive: false });

            // Also set onclick as fallback
            newLink.onclick = function(e) {
                const targetHref = this.getAttribute('href');
                console.log('[Training] onclick fallback triggered for:', targetHref);
                if (targetHref && targetHref.startsWith('/mobile/training/course/')) {
                    window.location.href = targetHref;
                    return false;
                }
            };
        });
    }

    // Run immediately and also after DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', setupCourseLinks);
    } else {
        setupCourseLinks();
    }

    // Also run after a short delay to catch dynamically added content
    setTimeout(setupCourseLinks, 1000);
});

async function downloadCourseForOffline(courseId) {
    if (!navigator.onLine) {
        alert('Downloading requires an internet connection.');
        return;
    }

    try {
        // Get course details and slides
        const response = await fetch(`/guardpro/api/training/course/${courseId}`);
        const data = await response.json();

        if (data.slides) {
            let downloaded = 0;
            const total = data.slides.length;

            for (const slide of data.slides) {
                if (slide.category !== 'quiz') {
                    // Cache slide content
                    await offlineManager.cacheSlideForOffline(slide.id, slide);
                    downloaded++;
                }
            }

            alert(`Downloaded ${downloaded} of ${total} slides for offline viewing.`);
        }
    } catch (error) {
        alert('Failed to download course content. Please try again.');
    }
}

let currentSlideId = null;
let currentQuizData = null;

// Helper function to show modal (works with or without Bootstrap)
function showModal(modalElement) {
    if (!modalElement) {
        console.error('[Training] Modal element not found');
        return;
    }

    // Try Bootstrap first
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        try {
            const bootstrapModal = new bootstrap.Modal(modalElement);
            bootstrapModal.show();
            return;
        } catch (e) {
            console.warn('[Training] Bootstrap Modal failed, using fallback:', e);
        }
    }

    // Fallback: Use vanilla JavaScript
    modalElement.style.display = 'block';
    modalElement.classList.add('show');
    modalElement.setAttribute('aria-hidden', 'false');
    modalElement.setAttribute('aria-modal', 'true');

    // Add backdrop
    let backdrop = document.querySelector('.modal-backdrop');
    if (!backdrop) {
        backdrop = document.createElement('div');
        backdrop.className = 'modal-backdrop fade show';
        backdrop.style.cssText = 'position: fixed; top: 0; left: 0; z-index: 1040; width: 100vw; height: 100vh; background-color: rgba(0, 0, 0, 0.5);';
        document.body.appendChild(backdrop);
    }

    // Prevent body scroll
    document.body.classList.add('modal-open');
    document.body.style.overflow = 'hidden';

    // Focus on modal
    const focusableElements = modalElement.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
    if (focusableElements.length > 0) {
        focusableElements[0].focus();
    }
}

// Helper function to hide modal
function hideModal(modalElement) {
    if (!modalElement) return;

    // Try Bootstrap first
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        try {
            const bootstrapModal = bootstrap.Modal.getInstance(modalElement);
            if (bootstrapModal) {
                bootstrapModal.hide();
                return;
            }
        } catch (e) {
            console.warn('[Training] Bootstrap Modal hide failed, using fallback:', e);
        }
    }

    // Fallback: Use vanilla JavaScript
    modalElement.style.display = 'none';
    modalElement.classList.remove('show');
    modalElement.setAttribute('aria-hidden', 'true');
    modalElement.removeAttribute('aria-modal');

    // Remove backdrop
    const backdrop = document.querySelector('.modal-backdrop');
    if (backdrop) {
        backdrop.remove();
    }

    // Restore body scroll
    document.body.classList.remove('modal-open');
    document.body.style.overflow = '';
}

// Add click handler for modal close buttons
document.addEventListener('DOMContentLoaded', function() {
    // Handle close buttons
    document.querySelectorAll('[data-bs-dismiss="modal"], .btn-close').forEach(btn => {
        btn.addEventListener('click', function() {
            const modal = this.closest('.modal');
            if (modal) {
                hideModal(modal);
            }
        });
    });

    // Handle backdrop clicks
    document.querySelectorAll('.modal').forEach(modal => {
        modal.addEventListener('click', function(e) {
            if (e.target === this) {
                hideModal(this);
            }
        });
    });

    // Handle ESC key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            const openModal = document.querySelector('.modal.show');
            if (openModal) {
                hideModal(openModal);
            }
        }
    });
});

// Offline slide caching
async function loadSlideWithOfflineFallback(slideId) {
    if (!slideId) {
        throw new Error('Slide ID is required');
    }

    if (!navigator.onLine) {
        // Try to load from cache first
        const cachedSlide = await offlineManager.getCachedSlide(slideId);
        if (cachedSlide) {
            return {
                slide: {
                    id: cachedSlide.id,
                    name: cachedSlide.name,
                    category: cachedSlide.category,
                    html_content: cachedSlide.html_content + '<div class="alert alert-info mt-3"><small><i class="fa fa-info-circle me-1"></i>Viewing offline cached content</small></div>',
                    completed: cachedSlide.completed,
                }
            };
        } else {
            throw new Error('You are offline and this slide is not available in cache. Please connect to the internet to view this content.');
        }
    }

    // Load from server
    console.log('[Training] Fetching slide from:', `/guardpro/api/training/slide/${slideId}`);

    try {
        const response = await fetch(`/guardpro/api/training/slide/${slideId}`, {
            method: 'GET',
            headers: {
                'Accept': 'application/json',
            },
            credentials: 'same-origin'
        });

        console.log('[Training] Response status:', response.status, response.statusText);

        if (!response.ok) {
            let errorData;
            try {
                errorData = await response.json();
                console.error('[Training] Error response:', errorData);
            } catch (e) {
                console.error('[Training] Failed to parse error response:', e);
                if (response.status === 404) {
                    errorData = { error: 'Slide not found. The training content may have been removed or moved.' };
                } else if (response.status === 403) {
                    errorData = { error: 'You do not have permission to view this content.' };
                } else if (response.status === 500) {
                    errorData = { error: 'Server error. Please try again later or contact support.' };
                } else {
                    errorData = { error: `Unable to load slide (Error ${response.status}). Please try again.` };
                }
            }
            throw new Error(errorData.error || `Unable to load slide (Error ${response.status})`);
        }

        const data = await response.json();
        console.log('[Training] Response data received:', data);

        // Validate response structure
        if (!data || typeof data !== 'object') {
            throw new Error('Invalid response from server. Please try again.');
        }

        if (!data.slide) {
            // If error message is present, use it
            if (data.error) {
                throw new Error(data.error);
            }
            throw new Error('Slide data not found in response. Please try again.');
        }

        // Ensure html_content exists
        if (!data.slide.html_content && data.slide.html_content !== '') {
            data.slide.html_content = '<div class="alert alert-warning"><p>Content is being prepared. Please try again later or contact your supervisor.</p></div>';
        }

        return data;
    } catch (error) {
        console.error('[Training] Fetch error:', error);
        // Re-throw with better message if it's not already an Error object
        if (error instanceof Error) {
            throw error;
        } else {
            throw new Error('Network error. Please check your connection and try again.');
        }
    }
}

// Helper function to get slide ID from button element
function getSlideIdFromButton(button) {
    if (!button) {
        console.error('[Training] Button element is null or undefined');
        return null;
    }

    // Try multiple methods to get the slide ID
    let slideId = button.getAttribute('data-slide-id');
    console.log('[Training] Initial slideId from data-slide-id:', slideId, typeof slideId);

    if (!slideId || slideId === '' || slideId === 'null' || slideId === 'undefined' || slideId === 'None') {
        // Try to get from button ID
        const buttonId = button.id;
        console.log('[Training] Trying button ID:', buttonId);
        if (buttonId && buttonId.startsWith('slide-btn-')) {
            slideId = buttonId.replace('slide-btn-', '');
        } else if (buttonId && buttonId.startsWith('quiz-btn-')) {
            slideId = buttonId.replace('quiz-btn-', '');
        }

        // If still not found, try to get from parent card
        if (!slideId || slideId === '' || slideId === 'null' || slideId === 'undefined') {
            const card = button.closest('.slide-card');
            if (card) {
                slideId = card.getAttribute('data-slide-id');
                console.log('[Training] Got slideId from parent card:', slideId);
            }
        }
    }

    // Validate and convert
    if (slideId) {
        // Convert to string and trim
        slideId = String(slideId).trim();

        // Check for invalid values
        if (slideId === '' || slideId === 'null' || slideId === 'undefined' || slideId === 'None' || slideId === '0') {
            console.warn('[Training] Slide ID is invalid:', slideId);
            return null;
        }

        // Try to parse as integer to validate it's a valid number
        const parsedId = parseInt(slideId, 10);
        if (isNaN(parsedId) || parsedId <= 0) {
            console.warn('[Training] Slide ID is not a valid positive integer:', slideId);
            return null;
        }

        // Return as string (API expects string or number)
        return parsedId.toString();
    }

    console.error('[Training] Could not find slide ID. Button:', button, 'Attributes:', {
        'data-slide-id': button.getAttribute('data-slide-id'),
        'id': button.id,
        'class': button.className,
        'parent-card': button.closest('.slide-card')?.getAttribute('data-slide-id')
    });

    return null;
}

// Function to handle slide button click
function handleSlideButtonClick(button, isQuiz = false) {
    // Ensure button is not disabled
    if (button.disabled) {
        console.warn('[Training] Button is disabled:', button);
        button.disabled = false;
    }

    // Ensure button is visible and clickable
    button.style.pointerEvents = 'auto';
    button.style.cursor = 'pointer';
    button.style.zIndex = '10';

    const slideId = getSlideIdFromButton(button);
    console.log('[Training] Button clicked, slideId:', slideId, typeof slideId, 'isQuiz:', isQuiz, 'Button:', button);

    if (!slideId) {
        console.error('[Training] Slide ID not found. Button attributes:', {
            'data-slide-id': button.getAttribute('data-slide-id'),
            'id': button.id,
            'parent-card': button.closest('.slide-card')?.getAttribute('data-slide-id'),
            'innerHTML': button.innerHTML.substring(0, 50),
            'disabled': button.disabled,
            'style': button.style.cssText
        });
        alert('Error: Slide ID not found. Please refresh the page. If the problem persists, contact your supervisor.');
        return;
    }

    // Show loading state on button
    const originalText = button.innerHTML;
    const originalDisabled = button.disabled;
    button.disabled = true;
    button.innerHTML = '<i class="fa fa-spinner fa-spin me-1"></i>Loading...';

    try {
        // Load slide or quiz
        if (isQuiz) {
            takeQuiz(slideId);
        } else {
            viewSlide(slideId);
        }

        // Restore button state after a short delay
        setTimeout(() => {
            button.disabled = originalDisabled;
            button.innerHTML = originalText;
        }, 1000);
    } catch (error) {
        console.error('[Training] Error handling button click:', error);
        button.disabled = originalDisabled;
        button.innerHTML = originalText;
        alert('Error loading content. Please try again.');
    }
}

// Use event delegation for better reliability
let delegationSetup = false;

function setupEventDelegation() {
    if (delegationSetup) {
        console.log('[Training] Event delegation already setup, skipping...');
        return;
    }

    console.log('[Training] Setting up event delegation...');

    // Use a single delegated handler on document
    function handleTrainingButtonClick(e) {
        const target = e.target.closest('.view-slide-btn, .take-quiz-btn');
        if (!target) return;

        // Don't handle if button is disabled
        if (target.disabled) {
            console.warn('[Training] Button is disabled, ignoring click');
            return;
        }

        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        const isQuiz = target.classList.contains('take-quiz-btn');
        handleSlideButtonClick(target, isQuiz);
    }

    function handleTrainingButtonTouch(e) {
        const target = e.target.closest('.view-slide-btn, .take-quiz-btn');
        if (!target) return;

        // Don't handle if button is disabled
        if (target.disabled) {
            console.warn('[Training] Button is disabled, ignoring touch');
            return;
        }

        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        const isQuiz = target.classList.contains('take-quiz-btn');
        handleSlideButtonClick(target, isQuiz);
    }

    // Attach handlers
    document.addEventListener('click', handleTrainingButtonClick, true); // Use capture phase
    document.addEventListener('touchend', handleTrainingButtonTouch, true);

    delegationSetup = true;
    console.log('[Training] Event delegation setup complete');
}

// Function to ensure buttons are clickable
function ensureButtonsClickable() {
    console.log('[Training] Ensuring buttons are clickable...');

    const allButtons = document.querySelectorAll('.view-slide-btn, .take-quiz-btn');
    console.log('[Training] Found', allButtons.length, 'training buttons');

    allButtons.forEach((btn, index) => {
        // Ensure button is not disabled (unless it should be)
        if (btn.disabled && !btn.hasAttribute('data-should-disable')) {
            console.log('[Training] Enabling disabled button:', index, btn);
            btn.disabled = false;
        }

        // Ensure CSS properties allow clicking
        btn.style.pointerEvents = 'auto';
        btn.style.cursor = 'pointer';
        btn.style.zIndex = '10';
        btn.style.position = 'relative';

        // Ensure data-slide-id is set
        if (!btn.getAttribute('data-slide-id')) {
            const card = btn.closest('.slide-card');
            if (card) {
                const cardSlideId = card.getAttribute('data-slide-id');
                if (cardSlideId) {
                    btn.setAttribute('data-slide-id', cardSlideId);
                    console.log('[Training] Set data-slide-id from card:', cardSlideId);
                }
            }
        }

        // Log button info for debugging
        console.log('[Training] Button', index, ':', {
            'data-slide-id': btn.getAttribute('data-slide-id'),
            'id': btn.id,
            'disabled': btn.disabled,
            'class': btn.className
        });
    });
}

document.addEventListener('DOMContentLoaded', function() {
    try {
        console.log('[Training] DOMContentLoaded - Initializing training handlers...');

        // Ensure buttons are clickable
        ensureButtonsClickable();

        // Setup event delegation
        setupEventDelegation();

        // Re-check after delays in case content loads dynamically
        setTimeout(() => {
            try {
                ensureButtonsClickable();
                setupEventDelegation();
            } catch (e) {
                console.error('[Training] Error in delayed initialization:', e);
            }
        }, 500);

        setTimeout(() => {
            try {
                ensureButtonsClickable();
                setupEventDelegation();
            } catch (e) {
                console.error('[Training] Error in delayed initialization:', e);
            }
        }, 2000);

        // Also check when page becomes visible (in case of lazy loading)
        document.addEventListener('visibilitychange', function() {
            if (!document.hidden) {
                setTimeout(() => {
                    try {
                        ensureButtonsClickable();
                    } catch (e) {
                        console.error('[Training] Error in visibility change handler:', e);
                    }
                }, 100);
            }
        });

        // Complete slide button handler
        const completeBtn = document.getElementById('completeSlideBtn');
        if (completeBtn) {
            completeBtn.addEventListener('click', function() {
                try {
                    completeSlide();
                } catch (e) {
                    console.error('[Training] Error in completeSlide:', e);
                    alert('Error completing slide. Please try again.');
                }
            });
        }

        // Submit quiz button handler
        const submitBtn = document.getElementById('submitQuizBtn');
        if (submitBtn) {
            submitBtn.addEventListener('click', function() {
                try {
                    submitQuiz();
                } catch (e) {
                    console.error('[Training] Error in submitQuiz:', e);
                    alert('Error submitting quiz. Please try again.');
                }
            });
        }
    } catch (e) {
        console.error('[Training] Error initializing training handlers:', e);
        // Fallback: try to attach handlers directly to buttons
        setTimeout(() => {
            try {
                document.querySelectorAll('.view-slide-btn, .take-quiz-btn').forEach(btn => {
                    btn.onclick = function() {
                        const slideId = this.getAttribute('data-slide-id');
                        if (slideId) {
                            if (this.classList.contains('take-quiz-btn')) {
                                takeQuiz(slideId);
                            } else {
                                viewSlide(slideId);
                            }
                        }
                    };
                });
            } catch (fallbackError) {
                console.error('[Training] Fallback handler also failed:', fallbackError);
            }
        }, 1000);
    }
});

async function viewSlide(slideId) {
    if (!slideId) {
        alert('Error: Slide ID is missing. Please refresh the page and try again.');
        return;
    }

    const modal = document.getElementById('slideModal');
    const modalTitle = document.getElementById('slideModalTitle');
    const modalBody = document.getElementById('slideModalBody');
    const completeBtn = document.getElementById('completeSlideBtn');

    // Show loading state
    modalTitle.textContent = 'Loading...';
    modalBody.innerHTML = '<div class="text-center py-5"><div class="spinner-border text-primary" role="status"><span class="visually-hidden">Loading...</span></div><p class="mt-3">Loading lesson content...</p></div>';
    completeBtn.style.display = 'none';

    // Show modal immediately with loading state
    showModal(modal);

    try {
        console.log('[Training] Loading slide:', slideId);
        const data = await loadSlideWithOfflineFallback(slideId);
        console.log('[Training] Slide data received:', data);

        if (data && data.slide) {
            currentSlideId = slideId;

            // Update modal with slide content
            modalTitle.textContent = data.slide.name || 'Lesson';

            // Ensure html_content is set
            let htmlContent = data.slide.html_content || '';
            if (!htmlContent || htmlContent.trim() === '') {
                const slideName = data.slide.name || 'Lesson';

                htmlContent = '<div class="alert alert-warning">' +
                    '<h5 class="alert-heading"><i class="fa fa-exclamation-triangle me-2"></i>Content Not Available</h5>' +
                    '<p><strong>' + slideName + '</strong></p>' +
                    '<p>This lesson content is being prepared for mobile viewing.</p>' +
                    '<div class="mt-2">' +
                    '<span class="badge bg-secondary me-1">Mobile Friendly</span>' +
                    '<span class="badge bg-info text-dark">Coming Soon</span>' +
                    '</div>' +
                    '<hr>' +
                    '<p class="mb-0"><small><i class="fa fa-info-circle me-1"></i>Please contact your supervisor to update this lesson so you can complete the course.</small></p>' +
                    '</div>';
            } else if (data.slide.category === 'quiz' && data.slide.has_quiz) {
                htmlContent = '<div class="alert alert-info">' +
                    '<h5 class="alert-heading"><i class="fa fa-question-circle me-2"></i>Knowledge Check</h5>' +
                    '<p><strong>' + (data.slide.name || 'Quiz') + '</strong></p>' +
                    '<p class="mb-3">Tap the button below to start this assessment.</p>' +
                    '<button class="btn btn-warning w-100" type="button" onclick="takeQuiz(' + slideId + ')">' +
                    '<i class="fa fa-question-circle me-1"></i>Take Quiz</button>' +
                    '</div>';
            }

            modalBody.innerHTML = htmlContent;

            // Handle completion button
            if (!navigator.onLine) {
                completeBtn.style.display = 'none';
                // Add offline indicator
                modalBody.innerHTML += '<div class="alert alert-warning mt-3"><small><i class="fa fa-wifi-slash me-1"></i>Offline mode - completion will sync when online</small></div>';
            } else {
                completeBtn.style.display = data.slide.completed ? 'none' : 'inline-block';
            }

            // Scroll to top of modal content
            modalBody.scrollTop = 0;
        } else {
            const errorMsg = data && data.error ? data.error : 'Slide data not found in response';
            console.error('[Training] No slide data in response:', data);

            modalTitle.textContent = 'Error Loading Content';
            modalBody.innerHTML = '<div class="alert alert-danger"><p><strong>Unable to load lesson content</strong></p><p>' + errorMsg + '</p><p class="mb-0"><small>Please try again or contact your supervisor if the problem persists.</small></p></div>';
            completeBtn.style.display = 'none';
        }
    } catch (error) {
        console.error('[Training] Error loading slide:', error);

        const errorMessage = error.message || 'An unexpected error occurred. Please try again.';

        modalTitle.textContent = 'Error Loading Content';
        modalBody.innerHTML = '<div class="alert alert-danger"><p><strong>Unable to load lesson content</strong></p><p>' + errorMessage + '</p><div class="mt-3"><button class="btn btn-primary btn-sm" onclick="location.reload()"><i class="fa fa-refresh me-1"></i>Refresh Page</button></div></div>';
        completeBtn.style.display = 'none';
    }
}

async function takeQuiz(slideId) {
    if (!slideId) {
        alert('Error: Quiz ID is missing. Please refresh the page and try again.');
        return;
    }

    const modal = document.getElementById('quizModal');
    const modalTitle = document.getElementById('quizModalTitle');
    const modalBody = document.getElementById('quizModalBody');
    const submitBtn = document.getElementById('submitQuizBtn');

    if (!modal || !modalTitle || !modalBody || !submitBtn) {
        console.error('[Training] Quiz modal elements not found:', {modal, modalTitle, modalBody, submitBtn});
        alert('Error: Quiz interface not available. Please refresh the page.');
        return;
    }

    // Reset modal state
    modalBody.style.overflowY = 'auto';
    modalBody.style.webkitOverflowScrolling = 'touch';

    // Show loading state
    modalTitle.textContent = 'Loading Quiz...';
    modalBody.innerHTML = '<div class="text-center py-5"><div class="spinner-border text-primary" role="status"><span class="visually-hidden">Loading...</span></div><p class="mt-3">Loading quiz questions...</p></div>';
    submitBtn.style.display = 'none';
    submitBtn.disabled = false;

    // Show modal immediately with loading state
    showModal(modal);

    try {
        console.log('[Training] Loading quiz:', slideId);
        const response = await fetch(`/guardpro/api/training/quiz/${slideId}`, {
            method: 'GET',
            headers: {
                'Accept': 'application/json',
            },
            credentials: 'same-origin'
        });

        if (!response.ok) {
            let errorData;
            try {
                errorData = await response.json();
            } catch (e) {
                if (response.status === 404) {
                    errorData = { error: 'Quiz not found. The quiz may have been removed or moved.' };
                } else if (response.status === 403) {
                    errorData = { error: 'You do not have permission to take this quiz.' };
                } else if (response.status === 500) {
                    errorData = { error: 'Server error. Please try again later or contact support.' };
                } else {
                    errorData = { error: `Unable to load quiz (Error ${response.status}). Please try again.` };
                }
            }
            throw new Error(errorData.error || `Unable to load quiz (Error ${response.status})`);
        }

        const data = await response.json();
        console.log('[Training] Quiz data received:', data);

        if (data && data.questions && Array.isArray(data.questions) && data.questions.length > 0) {
            currentSlideId = slideId;
            currentQuizData = data;
            modalTitle.textContent = data.slide_name || 'Quiz';

            let quizHtml = '<form id="quizForm">';
            let hasAnyAnswers = false;
            let hasAnyInputs = false;
            let questionCount = 0;

            data.questions.forEach((question, index) => {
                if (question && question.text) {
                    questionCount++;
                    quizHtml += '<div class="mb-4 quiz-question"><h6 class="mb-3">' + (index + 1) + '. ' + question.text + '</h6>';
                    const answers = (question.answers && Array.isArray(question.answers)) ? question.answers : [];
                    const allowText = question.allow_text || answers.length === 0;
                    let questionHasInputs = false;

                    if (answers.length > 0) {
                        question.answers.forEach(answer => {
                            if (answer && answer.id !== undefined && answer.text) {
                                hasAnyAnswers = true;
                                hasAnyInputs = true;
                                questionHasInputs = true;
                                quizHtml += '<div class="form-check mb-2">' +
                                    '<input class="form-check-input" type="radio" ' +
                                           'name="question_' + question.id + '" ' +
                                           'value="' + answer.id + '" ' +
                                           'id="answer_' + question.id + '_' + answer.id + '" required>' +
                                    '<label class="form-check-label" for="answer_' + question.id + '_' + answer.id + '">' +
                                        answer.text +
                                    '</label>' +
                                    '</div>';
                            }
                        });
                    } 

                    if (allowText) {
                        hasAnyInputs = true;
                        questionHasInputs = true;
                        quizHtml += '<div class="mb-2">' +
                            '<textarea class="form-control" rows="3" ' +
                            'name="question_' + question.id + '" ' +
                            'placeholder="Type your answer here..." required></textarea>' +
                            '</div>';
                    } else if (answers.length === 0 && !questionHasInputs) {
                        quizHtml += '<div class="alert alert-warning py-2"><small>No answer options available for this question.</small></div>';
                    }
                    quizHtml += '</div>';
                } else {
                    console.warn('[Training] Skipping invalid question:', question);
                }
            });
            quizHtml += '</form>';

            console.log('[Training] Quiz HTML generated. Questions:', questionCount, 'HasInputs:', hasAnyInputs);

            modalBody.innerHTML = quizHtml;
            submitBtn.style.display = 'inline-block';

            // Ensure modal body is visible and scrollable on mobile
            modalBody.style.overflowY = 'auto';
            modalBody.style.webkitOverflowScrolling = 'touch';

            // Double-check for inputs in the DOM after rendering (for mobile compatibility)
            setTimeout(() => {
                const form = document.getElementById('quizForm');
                if (!form) {
                    console.error('[Training] Quiz form not found in DOM after rendering');
                    submitBtn.disabled = true;
                    submitBtn.innerHTML = '<i class="fa fa-ban me-1"></i>Submit Disabled';
                    return;
                }

                const inputsInForm = form.querySelectorAll('input[type="radio"], textarea').length;
                const actualHasInputs = hasAnyInputs || inputsInForm > 0;

                console.log('[Training] Form check - hasAnyInputs:', hasAnyInputs, 'inputsInForm:', inputsInForm, 'actualHasInputs:', actualHasInputs);
                console.log('[Training] Form element:', form);
                console.log('[Training] Found inputs:', form.querySelectorAll('input[type="radio"], textarea'));

                if (!actualHasInputs || inputsInForm === 0) {
                    submitBtn.disabled = true;
                    submitBtn.innerHTML = '<i class="fa fa-ban me-1"></i>Submit Disabled';
                    console.warn('[Training] Submit button disabled - no inputs found. Question count:', questionCount);
                } else {
                    submitBtn.disabled = false;
                    submitBtn.innerHTML = '<i class="fa fa-paper-plane me-1"></i>Submit Quiz';
                    console.log('[Training] Submit button enabled with', inputsInForm, 'inputs');
                }
            }, 150);

            // Scroll to top of modal content
            setTimeout(() => {
                modalBody.scrollTop = 0;
            }, 200);
        } else {
            const errorMsg = data && data.error ? data.error : 'Quiz questions not found';
            console.error('[Training] Invalid quiz data:', data);
            console.error('[Training] Data structure:', JSON.stringify(data, null, 2));

            modalTitle.textContent = 'Error Loading Quiz';
            modalBody.innerHTML = '<div class="alert alert-danger"><p><strong>Unable to load quiz</strong></p><p>' + errorMsg + '</p><p class="mb-0"><small>Please try again or contact your supervisor if the problem persists.</small></p></div>';
            submitBtn.style.display = 'none';

            // Ensure modal is visible
            setTimeout(() => {
                modalBody.scrollTop = 0;
            }, 100);
        }
    } catch (error) {
        console.error('[Training] Error loading quiz:', error);
        console.error('[Training] Error stack:', error.stack);

        const errorMessage = error.message || 'An unexpected error occurred. Please try again.';

        modalTitle.textContent = 'Error Loading Quiz';
        modalBody.innerHTML = '<div class="alert alert-danger"><p><strong>Unable to load quiz</strong></p><p>' + errorMessage + '</p><div class="mt-3"><button class="btn btn-primary btn-sm" onclick="location.reload()"><i class="fa fa-refresh me-1"></i>Refresh Page</button></div></div>';
        submitBtn.style.display = 'none';

        // Ensure modal is visible
        setTimeout(() => {
            modalBody.scrollTop = 0;
        }, 100);
    }
}

async function completeSlide() {
    try {
        const response = await fetch(`/guardpro/api/training/slide/${currentSlideId}/complete`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            }
        });

        const data = await response.json();

        if (data.success) {
            hideModal(document.getElementById('slideModal'));
            location.reload(); // Refresh to show updated progress
        } else {
            alert(data.error || 'Failed to complete slide');
        }
    } catch (error) {
        alert('Network error. Please try again.');
    }
}

async function submitQuiz() {
    const form = document.getElementById('quizForm');
    const formData = new FormData(form);
    const answers = {};

    for (let [key, value] of formData.entries()) {
        const questionId = key.replace('question_', '');
        if (!answers[questionId]) answers[questionId] = [];
        answers[questionId].push(parseInt(value));
    }

    try {
        const response = await fetch(`/guardpro/api/training/quiz/${currentSlideId}/submit`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ answers })
        });

        const data = await response.json();

        if (data.success) {
            let message = data.passed ?
                `Quiz passed! Score: ${data.score.toFixed(1)}%` :
                `Quiz failed. Score: ${data.score.toFixed(1)}%. Please review and try again.`;

            alert(message);
            hideModal(document.getElementById('quizModal'));

            if (data.passed) {
                location.reload(); // Refresh to show updated progress
            }
        } else {
            alert(data.error || 'Failed to submit quiz');
        }
    } catch (error) {
        alert('Network error. Please try again.');
    }
}

window.guardproVisitorsExport = (function () {
    function parseFilename(contentDisposition) {
        if (!contentDisposition) {
            return 'visitors.xlsx';
        }
        var m = /filename\*=UTF-8''([^;]+)|filename="([^"]+)"/i.exec(contentDisposition);
        if (m) {
            try {
                return decodeURIComponent(m[1] || m[2] || 'visitors.xlsx');
            } catch (e) {
                return m[1] || m[2] || 'visitors.xlsx';
            }
        }
        return 'visitors.xlsx';
    }
    function download(btn) {
        var url = (btn && btn.getAttribute('data-export-url')) || '/guardpro/mobile/visitors/export';
        var original = btn ? btn.innerHTML : '';
        function restore() {
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = original;
            }
        }
        if (btn) {
            btn.disabled = true;
            btn.innerHTML = '<i class="fa fa-spinner fa-spin me-1"></i>Preparing…';
        }
        // Android app: native DownloadManager (reliable in WebView)
        if (window.AndroidBridge && typeof window.AndroidBridge.downloadUrl === 'function') {
            try {
                window.AndroidBridge.downloadUrl(url);
            } catch (e) {
                window.location.assign(url);
            }
            setTimeout(restore, 800);
            return;
        }
        fetch(url, { credentials: 'same-origin', cache: 'no-store' })
            .then(function (response) {
                if (!response.ok) {
                    throw new Error('HTTP ' + response.status);
                }
                var cd = response.headers.get('Content-Disposition');
                return response.blob().then(function (blob) {
                    return { blob: blob, filename: parseFilename(cd) };
                });
            })
            .then(function (payload) {
                if (window.AndroidBridge && typeof window.AndroidBridge.downloadBase64File === 'function') {
                    var reader = new FileReader();
                    reader.onload = function () {
                        var result = reader.result || '';
                        var b64 = result.indexOf(',') >= 0 ? result.split(',')[1] : result;
                        window.AndroidBridge.downloadBase64File(
                            payload.filename,
                            b64,
                            payload.blob.type || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
                        );
                        restore();
                    };
                    reader.onerror = function () {
                        window.location.assign(url);
                        restore();
                    };
                    reader.readAsDataURL(payload.blob);
                    return;
                }
                var objectUrl = URL.createObjectURL(payload.blob);
                var link = document.createElement('a');
                link.href = objectUrl;
                link.download = payload.filename;
                link.style.display = 'none';
                document.body.appendChild(link);
                link.click();
                setTimeout(function () {
                    URL.revokeObjectURL(objectUrl);
                    link.remove();
                    restore();
                }, 1500);
            })
            .catch(function () {
                window.location.assign(url);
                restore();
            });
    }
    return { download: download };
})();

div.script:
var gpHandover = (function() {
    var overlay = document.getElementById('gp-handover-overlay');
    function open(eqId, eqName) {
        document.getElementById('gp-handover-eq-id').value = eqId;
        document.getElementById('gp-handover-eq-name').innerHTML =
            '<i class="fa fa-cube me-1"></i>' + eqName;
        overlay.style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }
    function close() {
        overlay.style.display = 'none';
        document.body.style.overflow = '';
    }
    document.addEventListener('click', function(e) {
        if (e.target === overlay) close();
    });
    return { open: open, close: close };
})();

var gpKP = (function() {
    function switchTab(tab) {
        document.getElementById('tab-keys').style.display    = tab === 'keys'     ? 'block' : 'none';
        document.getElementById('tab-packages').style.display = tab === 'packages' ? 'block' : 'none';
        var kb = document.getElementById('tab-keys-btn');
        var pb = document.getElementById('tab-pkg-btn');
        if (kb) { kb.className = kb.className.replace(/border-primary text-primary|border-transparent text-muted/g, '');
                  kb.className += tab === 'keys' ? ' border-primary text-primary' : ' border-transparent text-muted'; }
        if (pb) { pb.className = pb.className.replace(/border-primary text-primary|border-transparent text-muted/g, '');
                  pb.className += tab === 'packages' ? ' border-primary text-primary' : ' border-transparent text-muted'; }
    }
    function openIssueKey() {
        var o = document.getElementById('gp-issue-key-overlay');
        if (o) { o.style.display = 'flex'; document.body.style.overflow = 'hidden'; }
    }
    function closeIssueKey() {
        var o = document.getElementById('gp-issue-key-overlay');
        if (o) { o.style.display = 'none'; document.body.style.overflow = ''; }
    }
    function openLogPackage() {
        var o = document.getElementById('gp-log-pkg-overlay');
        if (o) { o.style.display = 'flex'; document.body.style.overflow = 'hidden'; }
    }
    function closeLogPackage() {
        var o = document.getElementById('gp-log-pkg-overlay');
        if (o) { o.style.display = 'none'; document.body.style.overflow = ''; }
    }
    document.addEventListener('click', function(e) {
        var ik = document.getElementById('gp-issue-key-overlay');
        var lp = document.getElementById('gp-log-pkg-overlay');
        if (ik && e.target === ik) closeIssueKey();
        if (lp && e.target === lp) closeLogPackage();
    });
    return { switchTab: switchTab, openIssueKey: openIssueKey, closeIssueKey: closeIssueKey,
             openLogPackage: openLogPackage, closeLogPackage: closeLogPackage };
})();

var gpLFWizard = (function() {
    var _overlay, _step1, _step2, _dot1, _dot2, _catBadge, _catInput;

    function _init() {
        _overlay  = document.getElementById('gp-lf-wizard');
        _step1    = document.getElementById('gp-lf-step-1');
        _step2    = document.getElementById('gp-lf-step-2');
        _dot1     = document.getElementById('gp-lf-dot-1');
        _dot2     = document.getElementById('gp-lf-dot-2');
        _catBadge = document.getElementById('gp-lf-cat-badge');
        _catInput = document.getElementById('gp-lf-cat-input');
    }

    function open() {
        _init();
        goStep(1);
        _overlay.style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }

    function close() {
        if (_overlay) _overlay.style.display = 'none';
        document.body.style.overflow = '';
    }

    function goStep(n) {
        _init();
        _step1.style.display = n === 1 ? '' : 'none';
        _step2.style.display = n === 2 ? '' : 'none';
        _dot1.className = 'gp-step-dot' + (n >= 1 ? ' active' : '');
        _dot2.className = 'gp-step-dot' + (n >= 2 ? ' active' : '');
    }

    function pickCat(val, label) {
        _catInput.value = val;
        _catBadge.innerHTML = '<i class="fa fa-tag me-1"></i>' + label;
        goStep(2);
    }

    function previewPhoto(input) {
        var preview = document.getElementById('gp-lf-photo-preview');
        preview.innerHTML = '';
        if (input.files && input.files[0]) {
            var img = document.createElement('img');
            img.style.cssText = 'max-width:100%;max-height:160px;border-radius:8px;border:1px solid #e9ecef;';
            img.src = URL.createObjectURL(input.files[0]);
            preview.appendChild(img);
        }
    }

    function submit() {
        var desc = document.getElementById('gp-lf-desc').value.trim();
        var loc  = document.getElementById('gp-lf-loc').value.trim();
        var cat  = _catInput.value;
        if (!cat)  { alert('Please select an item category.'); goStep(1); return; }
        if (!desc) { alert('Please add a description.'); return; }
        if (!loc)  { alert('Please enter where the item was found.'); return; }
        document.getElementById('gp-lf-form').submit();
    }

    // Close on overlay click
    document.addEventListener('click', function(e) {
        if (_overlay && e.target === _overlay) close();
    });

    return { open: open, close: close, goStep: goStep, pickCat: pickCat,
             previewPhoto: previewPhoto, submit: submit };
})();
